6	namespace MonoDreams.Draw;
7	
8	/// <summary>
9	/// Interface for procedural mesh generation. Implementations create vertex/index data
10	/// for various shapes without coupling to game-specific logic.
11	/// </summary>
12	public interface IMeshGenerator
13	{
14	    MeshData Generate();
15	}
16	
17	/// <summary>
18	/// Generates a filled circle mesh using triangle fan pattern.
19	/// </summary>
20	public class CircleMeshGenerator : IMeshGenerator
21	{
22	    public Vector2 Center { get; set; }
23	    public float Radius { get; set; }
24	    public Color Color { get; set; }
25	    public int Segments { get; set; } = 16;
26	
27	    public CircleMeshGenerator(Vector2 center, float radius, Color color, int segments = 16)
28	    {
29	        Center = center;
30	        Radius = radius;
31	        Color = color;
32	        Segments = segments;
33	    }
34	
35	    public MeshData Generate()
36	    {
37	        var vertices = new List<VertexPositionColor>();
38	        var indices = new List<int>();
39	        int indexOffset = 0;
40	
41	        AddCircle(vertices, indices, Center, Radius, Color, ref indexOffset, Segments);
42	
43	        return new MeshData(vertices.ToArray(), indices.ToArray());
44	    }
45	
46	    public static void AddCircle(
47	        List<VertexPositionColor> vertices,
48	        List<int> indices,
49	        Vector2 center,
50	        float radius,
51	        Color color,
52	        ref int indexOffset,
53	        int segments = 16)
54	    {
55	        // Add center vertex
56	        vertices.Add(new VertexPositionColor(new Vector3(center, 0), color));
57	        int centerIndex = indexOffset++;
58	
59	        for (int i = 0; i < segments; i++)
60	        {
61	            float angle1 = 2 * MathF.PI * i / segments;
62	            float angle2 = 2 * MathF.PI * ((i + 1) % segments) / segments;
63	
64	            var point1 = new Vector2(
65	                center.X + radius * MathF.Cos(angle1),
66	                center.Y + radius * MathF.Sin(angle1));
67	
68	            var point2 = new Vector2(
69	                center.X + radius * MathF.Cos(angle2),
70	                center.Y + radius * MathF.Sin(angle2));
71	
72	            vertices.Add(new VertexPositionColor(new Vector3(point1, 0), color));
73	            vertices.Add(new VertexPositionColor(new Vector3(point2, 0), color));
74	
75	            indices.Add(centerIndex);
76	            indices.Add(indexOffset);
77	            indices.Add(indexOffset + 1);
78	
79	            indexOffset += 2;
80	        }
81	    }
82	}
83	
84	/// <summary>
85	/// Generates a hollow circle (ring) outline mesh — the circular analog of
86	/// <see cref="RectangleOutlineMeshGenerator"/>. The border is built from
87	/// <see cref="Segments"/> thick line quads connecting evenly spaced points around
88	/// the circumference, so the result is a triangle list just like the other
89	/// generators.
90	/// </summary>
91	public class CircleOutlineMeshGenerator : IMeshGenerator
92	{
93	    public Vector2 Center { get; set; }
94	    public float Radius { get; set; }
95	    public float Thickness { get; set; }
96	    public Color Color { get; set; }
97	    public int Segments { get; set; } = 24;
98	
99	    public CircleOutlineMeshGenerator(Vector2 center, float radius, float thickness, Color color, int segments = 24)
100	    {
101	        Center = center;
102	        Radius = radius;
103	        Thickness = thickness;
104	        Color = color;
105	        Segments = segments;
106	    }
107	
108	    public MeshData Generate()
109	    {
110	        var vertices = new List<VertexPositionColor>();
111	        var indices = new List<int>();
112	        int indexOffset = 0;
113	
114	        for (int i = 0; i < Segments; i++)
115	        {
116	            float angle1 = 2 * MathF.PI * i / Segments;
117	            float angle2 = 2 * MathF.PI * ((i + 1) % Segments) / Segments;
118	
119	            var point1 = new Vector2(
120	                Center.X + Radius * MathF.Cos(angle1),
121	                Center.Y + Radius * MathF.Sin(angle1));
122	            var point2 = new Vector2(
123	                Center.X + Radius * MathF.Cos(angle2),
124	                Center.Y + Radius * MathF.Sin(angle2));
125	
126	            LineMeshGenerator.AddLine(vertices, indices, point1, point2, Thickness, Color, ref indexOffset);
127	        }
128	
129	        return new MeshData(vertices.ToArray(), indices.ToArray());
130	    }
131	}
