10	namespace MonoDreams.Demos.UI;
11	
12	/// Helpers for building demo text entities and clickable menu buttons.
13	/// Centralizes the layout-friendly entity composition (transform + draw + outline
14	/// + interaction) that every demo screen would otherwise repeat.
15	public static class DemoUI
16	{
17	    public static Entity CreateText(
18	        World world,
19	        string text,
20	        BitmapFont font,
21	        Color color,
22	        float scale,
23	        float layerDepth,
24	        RenderTargetID target = RenderTargetID.Main)
25	    {
26	        var entity = world.CreateEntity();
27	        entity.Set(new TransformComponent(Vector2.Zero));
28	        entity.Set(new DynamicTextComponent
29	        {
30	            Target = target,
31	            LayerDepth = layerDepth,
32	            TextContent = text,
33	            Font = font,
34	            Color = color,
35	            Scale = scale,
36	            IsRevealed = true,
37	            VisibleCharacterCount = int.MaxValue,
38	        });
39	        entity.Set<VisibleComponent>();
40	        return entity;
41	    }
42	
43	    public static Vector2 MeasureText(Entity entity)
44	    {
45	        if (!entity.Has<DynamicTextComponent>()) return Vector2.Zero;
46	        ref var text = ref entity.Get<DynamicTextComponent>();
47	        var measured = text.Font.MeasureString(text.TextContent);
48	        return new Vector2(measured.Width * text.Scale, measured.Height * text.Scale);
49	    }
50	
51	    /// Creates a clickable menu button with a text label. Returns
52	    /// (container, outline, size) so the caller can attach the container to an
53	    /// AutoLayout slot and flip the active flag on the outline entity when the
54	    /// underlying selection changes.
55	    public static (Entity container, Entity outline, Vector2 size) CreateButton(
56	        World world,
57	        string id,
58	        string label,
59	        BitmapFont font,
60	        ButtonStyle style,
61	        float textLayerDepth,
62	        RenderTargetID target = RenderTargetID.Main,
63	        Color? activeColor = null)
64	    {
65	        var textSize = font.MeasureString(label) * style.TextScale;
66	        var buttonSize = new Vector2(
67	            textSize.Width + style.Padding * 2,
68	            textSize.Height + style.Padding * 2);
69	
70	        var container = world.CreateEntity();
71	        var containerTransform = new TransformComponent(Vector2.Zero);
72	        container.Set(containerTransform);
73	
74	        var textEntity = world.CreateEntity();
75	        textEntity.Set(new TransformComponent(new Vector2(style.Padding, style.Padding)));
76	        textEntity.SetParent(container);
77	        textEntity.Set(new DynamicTextComponent
78	        {
79	            Target = target,
80	            LayerDepth = textLayerDepth,
81	            TextContent = label,
82	            Font = font,
83	            Color = style.DefaultColor,
84	            Scale = style.TextScale,
85	            IsRevealed = true,
86	            VisibleCharacterCount = int.MaxValue,
87	        });
88	        textEntity.Set<VisibleComponent>();
89	
90	        var outline = world.CreateEntity();
91	        outline.Set(containerTransform);
92	        outline.Set(new SimpleButtonComponent
93	        {
94	            Size = buttonSize,
95	            LineThickness = style.BorderThickness,
96	            Color = style.BorderColor,
97	            TextEntity = textEntity,
98	            Target = target,
99	        });
100	        outline.Set(new DemoButtonComponent
101	        {
102	            Id = id,
103	            DefaultColor = style.DefaultColor,
104	            HoveredColor = style.HoveredColor,
105	            ActiveColor = activeColor ?? style.HoveredColor,
106	        });
107	        outline.Set<VisibleComponent>();
108	
109	        return (container, outline, buttonSize);
110	    }
111	
112	    /// Creates an icon-only clickable button (used for back / exit chrome). The
113	    /// container hosts a child sprite for the icon and an outline entity for
114	    /// hit-testing. Outline color is transparent so no border draws — interaction
115	    /// is signaled by recoloring the icon sprite on hover instead.
116	    public static (Entity container, Entity outline, Vector2 size) CreateIconButton(
117	        World world,
118	        string id,
119	        Texture2D iconSheet,
120	        Rectangle sourceRect,
121	        int sizePx,
122	        Color defaultTint,
123	        Color hoverTint,
124	        float layerDepth,
125	        RenderTargetID target = RenderTargetID.Main)
126	    {
127	        var buttonSize = new Vector2(sizePx, sizePx);
128	        var container = world.CreateEntity();
129	        var transform = new TransformComponent(Vector2.Zero);
130	        container.Set(transform);
131	
132	        // Icon sprite child — sits at (0,0) inside the container, scaled to sizePx.
133	        var icon = world.CreateEntity();
134	        icon.Set(new TransformComponent(
135	            Vector2.Zero,
136	            0f,
137	            new Vector2((float)sizePx / sourceRect.Width, (float)sizePx / sourceRect.Height)));
138	        icon.SetParent(container);
139	        icon.Set(new SpriteInfoComponent
140	        {
141	            SpriteSheet = iconSheet,
142	            Source = sourceRect,
143	            Size = buttonSize,
144	            Color = defaultTint,
145	            Target = target,
146	            LayerDepth = layerDepth,
147	        });
148	        icon.Set(new DrawComponent { Type = DrawElementType.Sprite, Target = target });
149	        icon.Set<VisibleComponent>();
150	
151	        // Outline entity: invisible (transparent), supplies SimpleButton for hit-test +
152	        // DemoButton for click dispatch. TextEntity points at the icon so the interaction
153	        // system can recolor it on hover/active.
154	        var outline = world.CreateEntity();
155	        outline.Set(transform);
156	        outline.Set(new SimpleButtonComponent
157	        {
158	            Size = buttonSize,
159	            LineThickness = 0f,
160	            Color = Color.Transparent,
161	            TextEntity = null,
162	            Target = target,
163	        });
164	        outline.Set(new DemoButtonComponent
165	        {
166	            Id = id,
167	            DefaultColor = defaultTint,
168	            HoveredColor = hoverTint,
169	            ActiveColor = hoverTint,
170	        });
171	        outline.Set<VisibleComponent>();
172	
173	        // Cross-link via a side component so a small extra system can recolor the icon.
174	        outline.Set(new IconRecolorTarget { Icon = icon });
175	
176	        return (container, outline, buttonSize);
177	    }
178	}
