196	{
197	    public Color LabelColor { get; init; } = Color.Black;
198	    public Color HoverColor { get; init; } = Color.OrangeRed;
199	    public Color ActiveColor { get; init; } = Color.DarkGreen;
200	    public float LabelScale { get; init; } = 0.14f;
