213	}
214	
215	/// Style data for a number-input row: an editable box plus its label. The box's
216	/// border + value text recolor on hover/focus via <see cref="DemoButtonComponent"/>
217	/// (focus is shown by reusing the button's <c>IsActive</c> accent), while the box
218	/// fill stays constant.
219	public class NumberInputStyle
220	{
221	    public Color LabelColor { get; init; } = Color.White;
222	    /// Border + value-text color when idle.
223	    public Color AccentColor { get; init; } = Color.White;
224	    /// Border + value-text color on hover.
225	    public Color HoverColor { get; init; } = Color.Yellow;
226	    /// Border + value-text color while focused.
227	    public Color FocusColor { get; init; } = Color.Gold;
228	    /// Box background fill (constant across states).
229	    public Color FillColor { get; init; } = Color.Transparent;
230	    public float BorderThickness { get; init; } = 2f;
231	    public float LabelScale { get; init; } = 0.18f;
232	    public float TextScale { get; init; } = 0.2f;
233	    public float Gap { get; init; } = 10f;
234	    public Vector2 BoxSize { get; init; } = new(48, 30);
235	    public float BoxPadding { get; init; } = 6f;
236	}
237	
238	public static partial class DemoUIRowExtensions
239	{
240	    /// Composite "number box + label" row. The box is a <see cref="SimpleButtonComponent"/>
241	    /// (border + fill + hit-test) carrying a <see cref="TextInputComponent"/>; clicking it
242	    /// is dispatched as a <see cref="DemoButtonClicked"/> so the screen can focus it, and
243	    /// <c>TextInputSystem</c> edits the value while focused. Returns the box/input entity
244	    /// as <c>Outline</c> — set its focus and read its <c>TextInputComponent.Text</c> there.
245	    public static (Entity Container, Entity Outline, Vector2 Size) CreateNumberInputRow(
246	        this World world,
247	        string id,
248	        string rowLabel,
249	        string initialValue,
250	        int maxLength,
251	        BitmapFont font,
252	        NumberInputStyle style,
253	        float layerDepth,
254	        RenderTargetID target = RenderTargetID.HUD)
255	    {
256	        var labelMeasured = font.MeasureString(rowLabel);
257	        var labelSize = new Vector2(labelMeasured.Width * style.LabelScale,
258	                                    labelMeasured.Height * style.LabelScale);
259	        var contentSize = new Vector2(style.BoxSize.X + style.Gap + labelSize.X,
260	                                      MathHelper.Max(style.BoxSize.Y, labelSize.Y));
261	
262	        var container = world.CreateEntity();
263	        var rowTransform = new TransformComponent(Vector2.Zero);
264	        container.Set(rowTransform);
265	
266	        // Value text inside the box, vertically centered, left-padded.
267	        var valueHeight = font.MeasureString("0").Height * style.TextScale;
268	        var valueText = world.CreateEntity();
269	        valueText.Set(new TransformComponent(new Vector2(style.BoxPadding, (style.BoxSize.Y - valueHeight) / 2f)));
270	        valueText.SetParent(container);
271	        valueText.Set(new DynamicTextComponent
272	        {
273	            Target = target,
274	            LayerDepth = layerDepth + 0.01f,
275	            TextContent = initialValue,
276	            Font = font,
277	            Color = style.AccentColor,
278	            Scale = style.TextScale,
279	            IsRevealed = true,
280	            VisibleCharacterCount = int.MaxValue,
281	        });
282	        valueText.Set<VisibleComponent>();
283	
284	        // Caret: a thin vertical line the TextInputSystem positions and shows while the box
285	        // is focused. Parented to the value text so it shares the text's origin — the system
286	        // only writes its local X (the rendered width up to the caret) and toggles its mesh.
287	        var caret = world.CreateEntity();
288	        caret.Set(new TransformComponent(Vector2.Zero));
289	        caret.SetParent(valueText);
290	        caret.Set(new DrawComponent
291	        {
292	            Type = DrawElementType.Mesh,
293	            Target = target,
294	            LayerDepth = layerDepth + 0.02f, // above the value text and the box outline
295	        });
296	        caret.Set<VisibleComponent>();
297	
298	        // Box outline = clickable hit area + border + fill, plus the input state.
299	        var outline = world.CreateEntity();
300	        outline.Set(rowTransform);
301	        outline.Set(new SimpleButtonComponent
302	        {
303	            Size = style.BoxSize,
304	            LineThickness = style.BorderThickness,
305	            Color = style.AccentColor,
306	            FillColor = style.FillColor,
307	            TextEntity = valueText,
308	            Target = target,
309	        });
310	        outline.Set(new DemoButtonComponent
311	        {
312	            Id = id,
313	            DefaultColor = style.AccentColor,
314	            HoveredColor = style.HoverColor,
315	            ActiveColor = style.FocusColor, // "active" == focused for an input box
316	            DefaultFillColor = style.FillColor,
317	            HoveredFillColor = style.FillColor,
318	            ActiveFillColor = style.FillColor,
319	        });
320	        outline.Set(new TextInputComponent
321	        {
322	            Text = initialValue,
323	            MaxLength = maxLength,
324	            Mask = TextInputMask.Numeric,
325	            Focused = false,
326	            TextEntity = valueText,
327	            CaretEntity = caret,
328	            CaretPosition = initialValue.Length, // start editing at the end of the pre-filled value
329	        });
330	        outline.Set<VisibleComponent>();
331	
332	        // Row label to the right of the box, vertically centered.
333	        var labelEntity = world.CreateEntity();
334	        labelEntity.Set(new TransformComponent(
335	            new Vector2(style.BoxSize.X + style.Gap, (contentSize.Y - labelSize.Y) / 2f)));
336	        labelEntity.SetParent(container);
337	        labelEntity.Set(new DynamicTextComponent
338	        {
339	            Target = target,
340	            LayerDepth = layerDepth + 0.01f,
341	            TextContent = rowLabel,
342	            Font = font,
343	            Color = style.LabelColor,
344	            Scale = style.LabelScale,
345	            IsRevealed = true,
346	            VisibleCharacterCount = int.MaxValue,
347	        });
348	        labelEntity.Set<VisibleComponent>();
349	
350	        return (container, outline, contentSize);
351	    }
352	
353	    /// Composite "key cap + label" row used by sidebar menus. The cap shows
354	    /// a small letter or digit on a sprite background; the row label is the
355	    /// human-readable command name. The whole row is one clickable hit-box.
356	    public static (Entity Container, Entity Outline, Vector2 Size) CreateKeyRow(
357	        this World world,
358	        string id,
359	        string keyLabel,
360	        string rowLabel,
361	        BitmapFont font,
362	        KeyCapStyle cap,
363	        KeyRowStyle row,
364	        float layerDepth,
365	        RenderTargetID target = RenderTargetID.HUD)
366	    {
367	        var capSize = new Vector2(cap.CapPixels, cap.CapPixels);
368	        var rowLabelMeasured = font.MeasureString(rowLabel);
369	        var rowLabelSize = new Vector2(rowLabelMeasured.Width * row.LabelScale,
370	                                       rowLabelMeasured.Height * row.LabelScale);
371	        var contentSize = new Vector2(capSize.X + row.Gap + rowLabelSize.X,
372	                                      MathHelper.Max(capSize.Y, rowLabelSize.Y));
373	        var padX = row.BackgroundPaddingX;
374	        var padY = row.BackgroundPaddingY;
375	        var rowSize = new Vector2(contentSize.X + padX * 2, contentSize.Y + padY * 2);
376	
377	        var container = world.CreateEntity();
378	        var rowTransform = new TransformComponent(Vector2.Zero);
379	        container.Set(rowTransform);
380	
381	        // Cap sprite — at left edge of row, vertically centered. Shifted by bg padding.
382	        var capYOffset = padY + (contentSize.Y - capSize.Y) / 2f;
383	        var spriteEntity = world.CreateEntity();
384	        spriteEntity.Set(new TransformComponent(new Vector2(padX, capYOffset)));
385	        spriteEntity.SetParent(container);
386	        spriteEntity.Set(new SpriteInfoComponent
387	        {
388	            SpriteSheet = cap.SpriteSheet,
389	            Source = cap.DefaultSource,
390	            Size = capSize,
391	            Color = Color.White,
392	            Target = target,
393	            LayerDepth = layerDepth,
394	        });
395	        spriteEntity.Set(new DrawComponent { Type = DrawElementType.Sprite, Target = target });
396	        spriteEntity.Set<VisibleComponent>();
397	
398	        // Cap label — centered inside the cap.
399	        var capLabelMeasured = font.MeasureString(keyLabel);
400	        var capLabelSize = new Vector2(capLabelMeasured.Width * cap.CapLabelScale,
401	                                       capLabelMeasured.Height * cap.CapLabelScale);
402	        var capLabelOffset = new Vector2(
403	            padX + (cap.CapPixels - capLabelSize.X) / 2f,
404	            capYOffset + (cap.CapPixels - capLabelSize.Y) / 2f);
405	        var capLabelEntity = world.CreateEntity();
406	        capLabelEntity.Set(new TransformComponent(capLabelOffset));
407	        capLabelEntity.SetParent(container);
408	        capLabelEntity.Set(new DynamicTextComponent
409	        {
410	            Target = target,
411	            LayerDepth = layerDepth + 0.01f,
412	            TextContent = keyLabel,
413	            Font = font,
414	            Color = cap.CapLabelColor,
415	            Scale = cap.CapLabelScale,
