203	    private SequentialSystem<GameState> CreateDrawSystem()
204	    {
205	        return new SequentialSystem<GameState>(
206	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
207	            new TextPrepSystem(_world, pixelPerfectRendering: false),
208	            new MeshPrepSystem(_world),
209	            // ButtonMeshPrepSystem must run AFTER MeshPrepSystem: button outlines are
210	            // baked in world coords and clear WorldMatrix to identity.
211	            new ButtonMeshPrepSystem(_world),
212	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
213	                RenderTargetID.Main, _renderTargets[RenderTargetID.Main], _camera),
214	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
215	                RenderTargetID.UI, _renderTargets[RenderTargetID.UI]),
216	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
217	                RenderTargetID.HUD, _renderTargets[RenderTargetID.HUD]),
218	            new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, new[]
219	            {
