    {
        if (_screenController == null) return;
        switch (msg.Id)
        {
            case "camera":
                _screenController.LoadScreen(DemoScreens.Camera);
                break;
            case "physics":
                _screenController.LoadScreen(DemoScreens.Physics);
                break;
            case "dialogue":
