1	using DefaultEcs.Threading;
2	using Microsoft.Xna.Framework;
3	using Microsoft.Xna.Framework.Graphics;
4	using Microsoft.Xna.Framework.Input;
5	using MonoDreams.Component;
6	using MonoDreams.Demos.Screens;
7	using MonoDreams.Demos.UI;
8	using MonoDreams.Renderer;
9	using MonoDreams.Screen;
10	using MonoDreams.State;
11	using MonoDreams.System.Debug;
12	using MonoDreams.System.Draw;
13	
14	namespace MonoDreams.Demos;
15	
16	public class Game1 : Game
17	{
18	    private const int VirtualWidth = 1280;
19	    private const int VirtualHeight = 720;
20	
21	    private GraphicsDeviceManager _graphics;
22	    private SpriteBatch _spriteBatch = null!;
23	    private ViewportManager _viewportManager;
24	    private Camera _camera;
25	    private DefaultParallelRunner _runner = null!;
26	    private ScreenController _screenController = null!;
27	
28	    private readonly HeadlessOptions _headless;
29	    private ScreenshotCaptureSystem? _screenshotCapture;
30	    private int _frame;
31	
32	    public Game1(string[]? args = null)
33	    {
34	        _headless = HeadlessOptions.Parse(args);
35	
36	        _graphics = new GraphicsDeviceManager(this);
37	        Content.RootDirectory = "Content";
38	        IsMouseVisible = false;
39	        _graphics.GraphicsProfile = GraphicsProfile.HiDef;
40	        // Headless still renders at full virtual resolution into a real backbuffer —
41	        // the window is just hidden off-screen and never relied on for presentation.
42	        // The render path (and its memory behaviour) is exercised exactly as in a
43	        // visible run, which is the whole point: a 1×1 window would make the captured
44	        // frame meaningless. See issue #28 and the debug-module premises.
45	        _graphics.PreferredBackBufferWidth = VirtualWidth;
46	        _graphics.PreferredBackBufferHeight = VirtualHeight;
47	        if (_headless.Enabled)
48	        {
49	            _graphics.SynchronizeWithVerticalRetrace = false;
50	            IsFixedTimeStep = false;
51	        }
52	        else
53	        {
54	            _graphics.SynchronizeWithVerticalRetrace = true;
55	            IsFixedTimeStep = true;
56	        }
57	        _graphics.ApplyChanges();
58	
59	        _viewportManager = new ViewportManager(this, VirtualWidth, VirtualHeight);
60	        _camera = new Camera(VirtualWidth, VirtualHeight);
61	
62	        Window.ClientSizeChanged += (_, _) => InitializeRenderer(GraphicsDevice.Viewport.Width, GraphicsDevice.Viewport.Height);
63	    }
64	
65	    private void InitializeRenderer(int realScreenWidth, int realScreenHeight)
66	    {
67	        _viewportManager.ScreenWidth = realScreenWidth;
68	        _viewportManager.ScreenHeight = realScreenHeight;
69	        _camera.RecalculateTransformationMatrices();
70	    }
71	
72	    protected override void Initialize()
73	    {
74	        var debugDir = global::System.Environment.GetEnvironmentVariable("MONODREAMS_DEBUG_DIR")
75	            ?? global::System.IO.Path.Combine(global::System.AppDomain.CurrentDomain.BaseDirectory, "debug");
76	        Logger.Initialize(debugDir);
77	
78	        // Project-wide dark navy theme for all MonoDreams demo screens.
79	        FinalDrawSystem.ClearColor = SproutPalette.DarkBg;
80	
81	        if (_headless.Enabled)
82	        {
83	            // Hide the window off-screen; the GL context (and its backbuffer) stay live
84	            // so Draw renders real frames we read back to PNG.
85	            Window.Position = new Point(-2000, -2000);
86	            _screenshotCapture = new ScreenshotCaptureSystem(GraphicsDevice, captureIntervalSeconds: 0f, debugDir);
87	            Logger.Info($"Headless run: screen='{_headless.Screen}', frames={_headless.Frames}, " +
88	                        $"captureEvery={_headless.CaptureEvery}, sampleEvery={_headless.SampleEvery}.");
89	        }
90	
91	        InitializeRenderer(GraphicsDevice.Viewport.Width, GraphicsDevice.Viewport.Height);
92	
93	        GraphicsDevice.RasterizerState = RasterizerState.CullCounterClockwise;
94	        GraphicsDevice.BlendState = BlendState.AlphaBlend;
95	
96	        _spriteBatch = new SpriteBatch(GraphicsDevice);
97	        _runner = new DefaultParallelRunner(1);
98	        _screenController = new ScreenController(this, _runner, _viewportManager, _camera, _spriteBatch, Content);
99	
100	        _screenController.RegisterScreen(DemoScreens.Launcher,
101	            () => new DemoLauncherScreen(GraphicsDevice, Content, _camera, _viewportManager, _spriteBatch));
102	        _screenController.RegisterScreen(DemoScreens.Camera,
103	            () => new MonoDreams.Demo.Camera.CameraDemoScreen(GraphicsDevice, Content, _camera, _viewportManager, _spriteBatch));
104	        _screenController.RegisterScreen(DemoScreens.Physics,
105	            () => new MonoDreams.Demo.Physics.PhysicsDemoScreen(GraphicsDevice, Content, _camera, _viewportManager, _spriteBatch, _runner));
106	        _screenController.RegisterScreen(DemoScreens.Dialogue,
107	            () => new MonoDreams.Demo.Dialogue.DialogueDemoScreen(GraphicsDevice, Content, _camera, _viewportManager, _spriteBatch));
108	
109	        // Headless jumps straight to the requested screen, skipping the launcher menu.
110	        _screenController.LoadScreen(_headless.Enabled ? _headless.Screen : DemoScreens.Launcher);
111	
112	        base.Initialize();
113	    }
114	
115	    protected override void Update(GameTime gameTime)
116	    {
117	        // Q exits the app from any screen; ESC is handled per-screen (typically
118	        // "back to launcher" inside a demo screen).
119	        if (!_headless.Enabled && Keyboard.GetState().IsKeyDown(Keys.Q))
120	            Exit();
121	        _screenController.Update(gameTime);
122	    }
123	
124	    protected override void Draw(GameTime gameTime)
125	    {
126	        // Headless deliberately does NOT early-return here (unlike the Examples host):
127	        // rendering every frame is what makes screenshots and render-path memory
128	        // behaviour observable.
129	        _screenController.Draw(gameTime);
130	
131	        if (_headless.Enabled)
132	            DriveHeadless(gameTime);
133	    }
134	
135	    /// Per-frame headless bookkeeping: heap sampling, screenshot capture, and auto-exit.
136	    /// Runs after the frame has been composited to the backbuffer so a capture reads a
137	    /// fully-rendered frame.
138	    private void DriveHeadless(GameTime gameTime)
139	    {
140	        var totalSeconds = (float)gameTime.TotalGameTime.TotalSeconds;
141	        var isFinalFrame = _frame >= _headless.Frames - 1;
142	
143	        if (_headless.SampleEvery > 0 && _frame % _headless.SampleEvery == 0)
144	        {
145	            // Force a collection so the sample reflects the *live* (retained) managed
146	            // heap, not transient per-frame churn that the GC hasn't reclaimed yet.
147	            // A retained-object leak (e.g. the per-frame EntitySet leak from #27)
148	            // survives the collection and still shows growth, so the series stays
149	            // assertable as "flat over a static scene"; ordinary allocation churn is
150	            // collected away and doesn't masquerade as a leak.
151	            var heapBytes = global::System.GC.GetTotalMemory(forceFullCollection: true);
152	            Logger.Info($"Heap sample: frame={_frame} gt={totalSeconds:F2} bytes={heapBytes}");
153	        }
154	
155	        var periodicCapture = _headless.CaptureEvery > 0 && _frame % _headless.CaptureEvery == 0;
156	        if (periodicCapture || isFinalFrame)
157	            _screenshotCapture?.CaptureNow(totalSeconds);
158	
159	        _frame++;
160	
161	        if (isFinalFrame)
162	        {
163	            Logger.Info($"Headless run complete after {_frame} frames. Exiting.");
164	            Exit();
165	        }
166	    }
167	
168	    protected override void Dispose(bool disposing)
169	    {
170	        _screenController.Dispose();
171	        _screenshotCapture?.Dispose();
172	        Logger.Shutdown();
173	        _runner.Dispose();
174	        _spriteBatch.Dispose();
175	        _graphics.Dispose();
176	        base.Dispose(disposing);
177	    }
178	}
