8	using MonoDreams.Component.Cursor;
9	using MonoDreams.Component.Draw;
10	using MonoDreams.Demos.Screens;
11	using MonoDreams.Demos.UI;
12	using MonoDreams.Draw;
13	using MonoDreams.Extension;
14	using MonoDreams.Renderer;
15	using MonoDreams.Screen;
16	using MonoDreams.State;
17	using MonoDreams.System;
18	using MonoDreams.System.Camera;
19	using MonoDreams.System.Cursor;
20	using MonoDreams.System.Draw;
21	using MonoDreams.UI;
22	using MonoGame.Extended.BitmapFonts;
23	
24	namespace MonoDreams.Demo.Camera;
25	
26	/// Camera module demo. Move a red circle inside a boundary rectangle with WASD/arrows;
27	/// switch between five fixed camera targets (numbered 1–5, each shown as a hoverable
28	/// region in the world) and a follow mode (key 0). The "smooth lerp" toggle controls
29	/// the damping on <see cref="CameraFollowTargetComponent"/>: when on, the camera eases
30	/// toward its target (ball in follow mode, or the corresponding zone center in fixed
31	/// modes); when off, it snaps instantly.
32	///
33	/// In follow mode the camera also zooms out a little as its center lags behind the
34	/// red dot — see <see cref="CameraLagZoomSystem"/>. The more the dot outruns the
35	/// camera (fast moves, or pushing into the camera-bounds edges), the wider the view.
36	///
37	/// Also in follow mode, when the red dot's center enters one of the four corner
38	/// zones the camera stops tracking the dot and instead prioritizes a fixed point a
39	/// little past that corner (a light-blue crosshair marks it) — see
40	/// <see cref="CornerPrioritySystem"/>. Leaving the corner zone hands tracking back
41	/// to the dot. This is the documented swap pattern: a second follow target whose
42	/// <see cref="CameraFollowTargetComponent.IsActive"/> flag we toggle against the ball's.
43	///
44	/// Finally, two hollow red squares flank the center zone (left and right, inside the
45	/// dashed camera-bounds rectangle). Driving the red dot into one fires a brief "hit" in any
46	/// camera mode: the square blinks yellow, and the camera takes a quick, decaying jolt on
47	/// top of its current motion — a positional <b>shake</b> from the right square, a small
48	/// <b>rotation</b> wobble from the left one — see <see cref="CameraHitSystem"/>. Both jolts
49	/// are layered on top of the resolved camera transform (last-write-wins, the documented
50	/// composable pattern), so they never fight <see cref="CameraFollowSystem"/>'s ownership of
51	/// the camera position.
52	public class CameraDemoScreen : IGameScreen
53	{
54	    private const float BoundaryHalfWidth = 380f;
55	    private const float BoundaryHalfHeight = 220f;
56	    // Camera-movement bounds in follow mode — a little smaller than the boundary,
57	    // so the red dot can push past the camera's reach toward the screen edges.
58	    private const float CameraBoundsHalfWidth = 280f;
59	    private const float CameraBoundsHalfHeight = 140f;
60	    private const float ZoneSize = 80f;
61	    private const float BallRadius = 20f;
62	    private const float MoveSpeed = 240f;
63	    // How far past the boundary corner the camera overshoots when the red dot
64	    // enters a corner zone — pushed well past the boundary on both axes.
65	    private const float CornerOverscan = 150f;
66	
67	    // Two little hollow red "hit" squares flanking the center, kept inside the dashed
68	    // camera-bounds rect (±CameraBounds). Driving the dot into one fires a camera jolt.
69	    private const float HitSquareSize = 50f;
70	    private const float HitSquareOffsetX = 150f;
71	    // How long a struck square flashes yellow before reverting to red.
72	    private const float HitBlinkDuration = 0.18f;
73	
74	    private const float DampingSmooth = 5f;
75	    private const float DampingInstant = 100f;
76	
77	    // Minimap: a second camera fixed at the region center, rendered to a small box
78	    // anchored to the bottom-right of the HUD. The box keeps the 16:9 virtual aspect
79	    // so the downscaled world view isn't distorted.
80	    private const int MinimapWidth = 320;
81	    private const int MinimapHeight = 180;
82	    private const int MinimapMargin = 24;
83	    // Fraction of the tightest fit, leaving a margin around the region in the minimap.
84	    private const float MinimapFitPadding = 0.85f;
85	
86	    /// Keyboard-key 0..5 maps directly to enum index: 0 Follow, 1 TL, 2 TR,
87	    /// 3 BR, 4 BL, 5 Center. Reordering is intentional — clockwise around the
88	    /// boundary corners with Center last.
89	    public enum Mode { Follow, FixedTL, FixedTR, FixedBR, FixedBL, FixedCenter }
90	
91	    /// Which flanking hit square (if any) the red dot currently sits in — <c>None</c> when
92	    /// the dot is clear of both. <see cref="CameraHitSystem"/> reads this to fire shake
93	    /// (Right) / rotate (Left).
94	    public enum HitZone { None, Left, Right }
95	
96	    private readonly ContentManager _content;
97	    private readonly GraphicsDevice _graphicsDevice;
98	    private readonly MonoDreams.Component.Camera _camera;
99	    private readonly ViewportManager _viewportManager;
100	    private readonly SpriteBatch _spriteBatch;
101	    private readonly World _world;
102	    private readonly Dictionary<RenderTargetID, RenderTarget2D> _renderTargets;
103	    private readonly BitmapFont _font;
104	    // Second camera + its own target for the minimap (see MinimapWidth/Height).
105	    private readonly MonoDreams.Component.Camera _minimapCamera;
106	    private readonly RenderTarget2D _minimapTarget;
107	
108	    private ScreenController? _screenController;
109	    private Entity _ball;
110	    private Entity _cameraAnchor;
111	    private Entity _lerpToggle;
112	    private Entity _targetCross;
113	    private Entity _cameraBoundsRect;
114	    // Free-following anchor the camera prioritizes while the red dot sits in a
115	    // corner zone; carries the light-blue corner crosshair as a child.
116	    private Entity _cornerAnchor;
117	    private Entity _cornerCross;
118	    // While corner priority is engaged, the distance from the prioritized point to
119	    // the corner zone's center; null when disengaged. Drives the corner zoom-out.
120	    private float? _cornerZoomDistance;
121	    // The two flanking hit squares and their remaining yellow-flash time (seconds).
122	    private Entity _leftHitSquare;
123	    private Entity _rightHitSquare;
124	    private float _leftBlink;
125	    private float _rightBlink;
126	    private Mode _mode = Mode.Follow;
127	    private bool _lerpSmooth = true;
128	
129	    private readonly Dictionary<Mode, Entity> _sidebarButtons = new();
130	    private readonly Dictionary<Mode, Entity> _worldZoneButtons = new();
131	
132	    public ISystem<GameState> UpdateSystem { get; }
133	    public ISystem<GameState> DrawSystem { get; }
134	    public World World => _world;
135	
136	    public CameraDemoScreen(GraphicsDevice graphicsDevice, ContentManager content, MonoDreams.Component.Camera camera,
137	        ViewportManager viewportManager, SpriteBatch spriteBatch)
138	    {
139	        _graphicsDevice = graphicsDevice;
140	        _content = content;
141	        _camera = camera;
142	        _viewportManager = viewportManager;
143	        _spriteBatch = spriteBatch;
144	        _renderTargets = new Dictionary<RenderTargetID, RenderTarget2D>
145	        {
146	            { RenderTargetID.Main, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
147	            { RenderTargetID.UI, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
148	            { RenderTargetID.HUD, new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight) },
149	        };
150	        _font = content.Load<BitmapFont>("Fonts/UAV-OSD-Sans-Mono-72-White-fnt");
151	
152	        camera.Position = Vector2.Zero;
153	
154	        // Minimap camera: same virtual resolution as the main camera (the mesh
155	        // projection is shared across render passes), fixed at the region center, and
156	        // zoomed so the whole boundary region fits with a margin. Never moved or zoomed.
157	        var fitZoom = Math.Min(
158	            viewportManager.VirtualWidth / (BoundaryHalfWidth * 2f),
159	            viewportManager.VirtualHeight / (BoundaryHalfHeight * 2f)) * MinimapFitPadding;
160	        _minimapCamera = new MonoDreams.Component.Camera(viewportManager.VirtualWidth, viewportManager.VirtualHeight)
161	        {
162	            Position = Vector2.Zero,
163	            Zoom = fitZoom,
164	        };
165	        _minimapTarget = new RenderTarget2D(graphicsDevice, viewportManager.VirtualWidth, viewportManager.VirtualHeight);
166	
167	        _world = new World();
168	        UpdateSystem = CreateUpdateSystem();
169	        DrawSystem = CreateDrawSystem();
170	    }
171	
172	    public void Load(ScreenController screenController, ContentManager content)
173	    {
174	        _screenController = screenController;
175	        _world.Subscribe<DemoButtonClicked>(OnButtonClicked);
176	
177	        var cursorTextures = new Dictionary<CursorType, Texture2D>
178	        {
179	            [CursorType.Default] = content.Load<Texture2D>("Cursor/default"),
180	            [CursorType.Pointer] = content.Load<Texture2D>("Cursor/pointer"),
181	            [CursorType.Hand] = content.Load<Texture2D>("Cursor/hand"),
182	        };
183	        MonoDreams.Cursor.Cursor.Create(_world, cursorTextures, RenderTargetID.HUD);
184	
185	        _cameraAnchor = _world.CreateEntity();
186	        _cameraAnchor.Set(new TransformComponent(Vector2.Zero));
187	
188	        CreateBoundary();
189	        CreateCameraBoundsRect();
190	        CreateWorldZones();
191	        CreateHitSquares();
192	        CreateBall();
193	        CreateTargetCross();
194	        CreateCornerPriorityAnchor();
195	        CreateCameraCenterCross();
196	        CreateMinimapFrame();
197	        BuildHud(content);
198	
199	        SetMode(_mode);
200	    }
201	
202	    // ─── public bridges for the keyboard system ───────────────────────────────
203	
204	    public void SetMode(Mode mode)
205	    {
206	        _mode = mode;
207	        foreach (var (m, btn) in _sidebarButtons) UpdateActive(btn, m == mode);
208	        foreach (var (m, btn) in _worldZoneButtons) UpdateActive(btn, m == mode);
209	
210	        // The dashed camera-bounds guide only makes sense while the camera tracks
211	        // the red dot — show it in follow mode, hide it in the fixed modes.
212	        SetCameraBoundsVisible(mode == Mode.Follow);
213	
214	        if (mode == Mode.Follow)
215	        {
216	            if (_cameraAnchor.Has<CameraFollowTargetComponent>())
217	                _cameraAnchor.Remove<CameraFollowTargetComponent>();
218	            if (!_ball.Has<CameraFollowTargetComponent>())
219	                _ball.Set(new CameraFollowTargetComponent());
220	            ApplyDampingTo(_ball);
221	            _ball.Get<CameraFollowTargetComponent>().Bounds = CameraBounds();
222	            ReparentTargetCross(_ball);
223	        }
224	        else
225	        {
226	            // Leaving follow mode hands the camera to the fixed anchor — make sure
227	            // any corner-priority override is cleared so it can't fight the anchor.
228	            DisengageCornerPriority();
229	            if (_ball.Has<CameraFollowTargetComponent>())
230	                _ball.Remove<CameraFollowTargetComponent>();
231	            var anchorTransform = _cameraAnchor.Get<TransformComponent>();
232	            anchorTransform.Position = ModeCameraTarget(mode);
233	            if (!_cameraAnchor.Has<CameraFollowTargetComponent>())
234	                _cameraAnchor.Set(new CameraFollowTargetComponent());
235	            ApplyDampingTo(_cameraAnchor);
236	            ReparentTargetCross(_cameraAnchor);
237	
238	            if (!_lerpSmooth) _camera.Position = anchorTransform.Position;
239	        }
240	    }
241	
242	    private void ReparentTargetCross(Entity newParent)
243	    {
244	        if (!_targetCross.IsAlive) return;
245	        // SetParent overwrites ChildOfComponent + transform.Parent in place;
246	        // we deliberately skip RemoveParent so the cross's LOCAL position stays
247	        // at (0,0). RemoveParent snapshots the current world position into the
248	        // local one, which would double the offset on the next reparent.
249	        _targetCross.SetParent(newParent);
250	        _targetCross.Get<TransformComponent>().Position = Vector2.Zero;
251	    }
252	
253	    public void GoBackToLauncher() => _screenController?.LoadScreen(DemoScreens.Launcher);
254	
255	    public void ToggleLerp()
256	    {
257	        if (!_lerpToggle.IsAlive || !_lerpToggle.Has<ToggleSwitchComponent>()) return;
258	        var sw = _lerpToggle.Get<ToggleSwitchComponent>();
259	        sw.On = !sw.On;
260	        _lerpSmooth = sw.On;
261	        _lerpToggle.Set(sw);
262	
263	        if (_ball.Has<CameraFollowTargetComponent>()) ApplyDampingTo(_ball);
264	        if (_cornerAnchor.IsAlive && _cornerAnchor.Has<CameraFollowTargetComponent>()) ApplyDampingTo(_cornerAnchor);
265	        if (_cameraAnchor.Has<CameraFollowTargetComponent>())
266	        {
267	            ApplyDampingTo(_cameraAnchor);
268	            if (!_lerpSmooth) _camera.Position = _cameraAnchor.Get<TransformComponent>().Position;
269	        }
270	    }
271	
272	    private void ApplyDampingTo(Entity target)
273	    {
274	        if (!target.Has<CameraFollowTargetComponent>()) return;
275	        var ft = target.Get<CameraFollowTargetComponent>();
276	        ft.DampingX = _lerpSmooth ? DampingSmooth : DampingInstant;
277	        ft.DampingY = _lerpSmooth ? DampingSmooth : DampingInstant;
278	        ft.MaxDistanceX = 10000f;
279	        ft.MaxDistanceY = 10000f;
280	    }
281	
282	    /// Per-frame corner-priority tick, driven by <see cref="CornerPrioritySystem"/>.
283	    /// Only engages in follow mode: when the red dot's center is inside a corner zone,
284	    /// the camera prioritizes the corner's overscan point (light-blue cross) by toggling
285	    /// the corner anchor active and the ball inactive; otherwise the ball stays the
286	    /// target. Runs after the ball moves and after mode switches, before the follow
287	    /// system, so at most one target is active when <see cref="CameraFollowSystem"/> reads.
288	    public void UpdateCornerPriority()
289	    {
290	        if (_mode != Mode.Follow)
291	        {
292	            DisengageCornerPriority();
293	            return;
294	        }
295	
296	        var ballCenter = _ball.Get<TransformComponent>().Position;
297	        if (TryGetCornerZone(ballCenter, out var corner))
298	        {
299	            var point = CornerPriorityPoint(corner);
300	            _cornerAnchor.Get<TransformComponent>().Position = point;
301	            _cornerAnchor.Get<CameraFollowTargetComponent>().IsActive = true;
302	            if (_ball.Has<CameraFollowTargetComponent>())
303	                _ball.Get<CameraFollowTargetComponent>().IsActive = false;
304	            SetCornerCrossVisible(true);
305	            // How far the prioritized point sits beyond the corner zone's center —
306	            // CameraLagZoomSystem reads this to zoom out proportionally.
307	            _cornerZoomDistance = (point - CornerZoneCenter(corner)).Length();
308	        }
309	        else
310	        {
311	            DisengageCornerPriority();
312	        }
313	    }
314	
315	    /// Distance the prioritized corner point sits from the corner zone's center while
316	    /// corner priority is engaged; null otherwise. Read by <see cref="CameraLagZoomSystem"/>.
317	    public float? CornerZoomDistance => _cornerZoomDistance;
318	
319	    /// Which flanking hit square the red dot currently sits in, or <c>None</c>.
320	    /// <see cref="CameraHitSystem"/> reads this and fires on the rising edge (the dot
321	    /// entering a square), in any camera mode.
322	    public HitZone BallHitZone
323	    {
324	        get
325	        {
326	            if (!_ball.IsAlive) return HitZone.None;
327	            var center = _ball.Get<TransformComponent>().Position;
328	            if (HitSquareRect(-HitSquareOffsetX).Contains((int)center.X, (int)center.Y)) return HitZone.Left;
329	            if (HitSquareRect(HitSquareOffsetX).Contains((int)center.X, (int)center.Y)) return HitZone.Right;
330	            return HitZone.None;
331	        }
332	    }
333	
334	    /// World-space rectangle of a hit square centred at <paramref name="centerX"/> on the
335	    /// horizontal axis (the squares straddle y = 0).
336	    private static Rectangle HitSquareRect(float centerX)
337	    {
338	        var half = (int)(HitSquareSize / 2f);
339	        return new Rectangle((int)centerX - half, -half, (int)HitSquareSize, (int)HitSquareSize);
340	    }
341	
342	    /// Flashes the struck square yellow and (re)starts its blink timer. Called by
343	    /// <see cref="CameraHitSystem"/> on the frame the dot enters the square.
344	    public void BlinkHitSquare(HitZone zone)
345	    {
346	        switch (zone)
347	        {
348	            case HitZone.Left:  _leftBlink = HitBlinkDuration;  SetHitSquareColor(_leftHitSquare, SproutPalette.SoftYellow); break;
349	            case HitZone.Right: _rightBlink = HitBlinkDuration; SetHitSquareColor(_rightHitSquare, SproutPalette.SoftYellow); break;
350	        }
351	    }
352	
353	    /// Ticks down the yellow flashes; when one expires its square reverts to red. Driven
354	    /// each frame by <see cref="CameraHitSystem"/>. Colors are only rewritten on the
355	    /// expiry transition, not every frame.
356	    public void UpdateHitSquareBlinks(float dt)
357	    {
358	        if (_leftBlink > 0f && (_leftBlink -= dt) <= 0f)
359	        {
360	            _leftBlink = 0f;
361	            SetHitSquareColor(_leftHitSquare, SproutPalette.Crimson);
362	        }
363	        if (_rightBlink > 0f && (_rightBlink -= dt) <= 0f)
364	        {
365	            _rightBlink = 0f;
366	            SetHitSquareColor(_rightHitSquare, SproutPalette.Crimson);
367	        }
368	    }
