395	    /// True when <paramref name="ballCenter"/> lies inside one of the four corner zones,
396	    /// yielding which corner it is.
397	    private static bool TryGetCornerZone(Vector2 ballCenter, out Mode corner)
398	    {
399	        foreach (var mode in CornerModes)
400	        {
401	            var topLeft = ZoneTopLeft(mode);
402	            var zone = new Rectangle((int)topLeft.X, (int)topLeft.Y, (int)ZoneSize, (int)ZoneSize);
403	            if (zone.Contains((int)ballCenter.X, (int)ballCenter.Y))
404	            {
405	                corner = mode;
406	                return true;
407	            }
408	        }
409	        corner = Mode.Follow;
410	        return false;
411	    }
