418	    /// boundary corner pushed out by <see cref="CornerOverscan"/> on both axes.
419	    private static Vector2 CornerPriorityPoint(Mode m) => m switch
420	    {
421	        Mode.FixedTL => new Vector2(-BoundaryHalfWidth - CornerOverscan, -BoundaryHalfHeight - CornerOverscan),
422	        Mode.FixedTR => new Vector2( BoundaryHalfWidth + CornerOverscan, -BoundaryHalfHeight - CornerOverscan),
423	        Mode.FixedBR => new Vector2( BoundaryHalfWidth + CornerOverscan,  BoundaryHalfHeight + CornerOverscan),
424	        Mode.FixedBL => new Vector2(-BoundaryHalfWidth - CornerOverscan,  BoundaryHalfHeight + CornerOverscan),
425	        _ => Vector2.Zero,
