436	    // corners offset by half the zone size so the zone sprite is fully on-screen.
437	    private static Vector2 ModeCameraTarget(Mode m)
438	    {
439	        var halfZone = ZoneSize / 2f;
440	        return m switch
441	        {
442	            Mode.FixedTL     => new Vector2(-BoundaryHalfWidth + halfZone, -BoundaryHalfHeight + halfZone),
443	            Mode.FixedTR     => new Vector2( BoundaryHalfWidth - halfZone, -BoundaryHalfHeight + halfZone),
444	            Mode.FixedCenter => Vector2.Zero,
445	            Mode.FixedBL     => new Vector2(-BoundaryHalfWidth + halfZone,  BoundaryHalfHeight - halfZone),
446	            Mode.FixedBR     => new Vector2( BoundaryHalfWidth - halfZone,  BoundaryHalfHeight - halfZone),
447	            _                => Vector2.Zero,
448	        };
449	    }
