865	    private SequentialSystem<GameState> CreateUpdateSystem()
866	    {
867	        return new SequentialSystem<GameState>(
868	            new CursorInputSystem(_world),
869	            new IntrinsicSizingSystem(_world),
870	            new AutoLayoutSystem(_world, _viewportManager),
871	            new DemoButtonInteractionSystem(_world),
872	            new DemoIconRecolorSystem(_world),
873	            new ToggleSwitchSystem(_world),
874	            new PlayerBallMovementSystem(_world, BoundaryHalfWidth, BoundaryHalfHeight, BallRadius, MoveSpeed),
875	            new CameraDemoInputSystem(this),
876	            // Runs after the ball moved and after mode switches, before the follow
877	            // system, so the right target is active when the camera resolves.
878	            new CornerPrioritySystem(this),
879	            new CameraFollowSystem(_world, _camera),
880	            // Runs after the follow system so it reads this frame's resolved
881	            // camera position when measuring the lag behind the red dot.
882	            new CameraLagZoomSystem(_world, _camera, this),
883	            new HierarchySystem(_world),
884	            new CursorPositionSystem(_world, _camera, _viewportManager),
885	            new CursorDrawPrepSystem(_world),
886	            // Hit jolts run last so only rendering sees the offset/rotation — cursor and
887	            // hierarchy this frame already used the clean follow transform, and the system
888	            // peels off its own prior offset before re-applying, so the jolt never bleeds
889	            // into the follow path.
890	            new CameraHitSystem(_camera, this));
891	    }
892	
893	    private SequentialSystem<GameState> CreateDrawSystem()
894	    {
895	        return new SequentialSystem<GameState>(
896	            new SpritePrepSystem(_world, _graphicsDevice, pixelPerfectRendering: false),
897	            new TextPrepSystem(_world, pixelPerfectRendering: false),
898	            new MeshPrepSystem(_world),
899	            new ButtonMeshPrepSystem(_world),
900	            // World view through the main camera, plus screen-space UI/HUD passes.
901	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
902	                RenderTargetID.Main, _renderTargets[RenderTargetID.Main], _camera),
903	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
904	                RenderTargetID.UI, _renderTargets[RenderTargetID.UI]),
905	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
906	                RenderTargetID.HUD, _renderTargets[RenderTargetID.HUD]),
907	            // Minimap: the same world (Main) entities through a second camera fixed at the
908	            // region center, rendered into its own target — just another render pass.
909	            new MasterRenderSystem(_spriteBatch, _graphicsDevice, _world,
910	                RenderTargetID.Main, _minimapTarget, _minimapCamera),
911	            // Composite the targets onto the screen; the minimap lands in its bottom-right box.
912	            new FinalDrawSystem(_spriteBatch, _graphicsDevice, _viewportManager, new[]
913	            {
914	                RenderLayer.Main(_renderTargets[RenderTargetID.Main]),
915	                RenderLayer.UI(_renderTargets[RenderTargetID.UI]),
916	                RenderLayer.HUD(_renderTargets[RenderTargetID.HUD]),
917	                RenderLayer.Overlay(_minimapTarget, MinimapDestination(), SamplerState.LinearClamp),
918	            }));
919	    }
920	
921	    public void Dispose()
922	    {
923	        UpdateSystem.Dispose();
924	        DrawSystem.Dispose();
925	        foreach (var rt in _renderTargets.Values) rt.Dispose();
926	        _minimapTarget.Dispose();
927	        _world.Dispose();
928	        GC.SuppressFinalize(this);
929	    }
930	}
931	
932	/// Tag identifying the player-controlled circle in the camera demo.
933	public struct PlayerBallTag { }
934	
935	/// Reads keyboard input (WASD + arrows) and translates the tagged player entity,
936	/// clamping its position so the ball stays inside the boundary rectangle.
937	[With(typeof(PlayerBallTag), typeof(TransformComponent))]
938	public class PlayerBallMovementSystem : AEntitySetSystem<GameState>
939	{
940	    private readonly float _halfWidth;
941	    private readonly float _halfHeight;
942	    private readonly float _radius;
943	    private readonly float _speed;
944	
945	    public PlayerBallMovementSystem(World world, float halfWidth, float halfHeight, float radius, float speed)
946	        : base(world)
947	    {
948	        _halfWidth = halfWidth;
949	        _halfHeight = halfHeight;
950	        _radius = radius;
951	        _speed = speed;
952	    }
953	
954	    protected override void Update(GameState state, in Entity entity)
955	    {
956	        var keyboard = Keyboard.GetState();
957	        var dir = Vector2.Zero;
958	        if (keyboard.IsKeyDown(Keys.A) || keyboard.IsKeyDown(Keys.Left))  dir.X -= 1f;
959	        if (keyboard.IsKeyDown(Keys.D) || keyboard.IsKeyDown(Keys.Right)) dir.X += 1f;
960	        if (keyboard.IsKeyDown(Keys.W) || keyboard.IsKeyDown(Keys.Up))    dir.Y -= 1f;
961	        if (keyboard.IsKeyDown(Keys.S) || keyboard.IsKeyDown(Keys.Down))  dir.Y += 1f;
962	        if (dir != Vector2.Zero) dir.Normalize();
963	
964	        var transform = entity.Get<TransformComponent>();
965	        var next = transform.Position + dir * _speed * state.Time;
966	        next.X = MathHelper.Clamp(next.X, -_halfWidth + _radius, _halfWidth - _radius);
967	        next.Y = MathHelper.Clamp(next.Y, -_halfHeight + _radius, _halfHeight - _radius);
968	        transform.Position = next;
969	    }
970	}
