972	/// Polls the keyboard for camera-mode shortcuts (0–5, L) and forwards them
973	/// to the owning <see cref="CameraDemoScreen"/>. Edge-triggered: each key press
974	/// fires once per release-then-press cycle.
975	public class CameraDemoInputSystem : ISystem<GameState>
976	{
977	    private readonly CameraDemoScreen _screen;
978	    private KeyboardState _previous;
979	    public bool IsEnabled { get; set; } = true;
980	
981	    public CameraDemoInputSystem(CameraDemoScreen screen)
982	    {
983	        _screen = screen;
984	        _previous = Keyboard.GetState();
985	    }
