987	    public void Update(GameState state)
988	    {
989	        if (!IsEnabled) return;
990	        var current = Keyboard.GetState();
991	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
992	
993	        if (Pressed(Keys.D0) || Pressed(Keys.NumPad0)) _screen.SetMode(CameraDemoScreen.Mode.Follow);
994	        if (Pressed(Keys.D1) || Pressed(Keys.NumPad1)) _screen.SetMode(CameraDemoScreen.Mode.FixedTL);
995	        if (Pressed(Keys.D2) || Pressed(Keys.NumPad2)) _screen.SetMode(CameraDemoScreen.Mode.FixedTR);
996	        if (Pressed(Keys.D3) || Pressed(Keys.NumPad3)) _screen.SetMode(CameraDemoScreen.Mode.FixedBR);
997	        if (Pressed(Keys.D4) || Pressed(Keys.NumPad4)) _screen.SetMode(CameraDemoScreen.Mode.FixedBL);
998	        if (Pressed(Keys.D5) || Pressed(Keys.NumPad5)) _screen.SetMode(CameraDemoScreen.Mode.FixedCenter);
999	        if (Pressed(Keys.L)) _screen.ToggleLerp();
1000	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
1001	
1002	        _previous = current;
1003	    }
