1008	/// Drives the screen's corner-priority override each frame (see
1009	/// <see cref="CameraDemoScreen.UpdateCornerPriority"/>). The screen owns the entities
1010	/// and mode state, so the per-frame tick lives there; this system just forwards it at
1011	/// the right pipeline slot — after movement/mode switches, before the follow system.
1012	public class CornerPrioritySystem : ISystem<GameState>
1013	{
1014	    private readonly CameraDemoScreen _screen;
1015	    public bool IsEnabled { get; set; } = true;
1016	
1017	    public CornerPrioritySystem(CameraDemoScreen screen) => _screen = screen;
1018	
1019	    public void Update(GameState state)
1020	    {
1021	        if (!IsEnabled) return;
1022	        _screen.UpdateCornerPriority();
1023	    }
1024	
1025	    public void Dispose() => GC.SuppressFinalize(this);
