1027	
1028	/// Zooms the camera out a little, and eases the applied zoom toward that target so it
1029	/// widens and recovers smoothly. Two sources drive the zoom-out:
1030	///
1031	/// 1. <b>Follow lag</b> — while the red dot is the active target, the world-space
1032	///    distance between the ball and the resolved camera position. It grows when the
1033	///    dot outruns the camera or pushes past the camera-bounds edges.
1034	/// 2. <b>Corner priority</b> — while the camera prioritizes a corner point (the dot
1035	///    sits in a corner zone), the distance from that point to the corner zone's center
1036	///    (<see cref="CameraDemoScreen.CornerZoomDistance"/>). This is the dominant source
1037	///    when engaged, so the view stays widened the whole time it looks past the corner.
1038	///
1039	/// Each distance maps linearly to a zoom reduction, capped at <see cref="MaxZoomOut"/>.
1040	/// When neither applies (fixed modes, dot centered) the target zoom is 1. This only
1041	/// writes <c>Camera.Zoom</c>, so it never competes with <see cref="CameraFollowSystem"/>'s
1042	/// ownership of <c>Camera.Position</c>.
1043	public class CameraLagZoomSystem : ISystem<GameState>
1044	{
1045	    // Follow-lag distance (in world units) at which the zoom-out reaches its full
1046	    // MaxZoomOut. Sized for this demo's boundary/camera-bounds geometry.
1047	    private const float MaxLag = 150f;
1048	    // Corner-priority distance (blue point ↔ corner center) that maps to full MaxZoomOut.
1049	    // Kept above the geometry's actual ~270px so the corner zoom stays proportional
1050	    // (below the cap) and scales if the overscan changes.
1051	    private const float CornerZoomReferenceDistance = 320f;
1052	    // Largest zoom reduction; 0.18 means the camera widens to at most 0.82× — "a little".
1053	    private const float MaxZoomOut = 0.18f;
1054	    // Exponential easing rate for the applied zoom, matched to the smooth-lerp feel.
1055	    private const float ZoomDamping = 6f;
1056	
1057	    private readonly MonoDreams.Component.Camera _camera;
1058	    private readonly CameraDemoScreen _screen;
1059	    private readonly EntitySet _activeBallTargets;
1060	    private float _currentZoom = 1f;
1061	
1062	    public bool IsEnabled { get; set; } = true;
1063	
1064	    public CameraLagZoomSystem(World world, MonoDreams.Component.Camera camera, CameraDemoScreen screen)
1065	    {
1066	        _camera = camera;
1067	        _screen = screen;
1068	        // The ball only carries CameraFollowTargetComponent while in follow mode, so
1069	        // this set is non-empty exactly when the dot is the camera target.
1070	        _activeBallTargets = world.GetEntities()
1071	            .With<PlayerBallTag>()
1072	            .With<CameraFollowTargetComponent>()
1073	            .With<TransformComponent>()
1074	            .AsSet();
1075	    }
1076	
1077	    public void Update(GameState state)
1078	    {
1079	        if (!IsEnabled) return;
1080	
1081	        var targetZoom = 1f;
1082	        if (_screen.CornerZoomDistance is { } cornerDistance)
1083	        {
1084	            // Corner priority owns the zoom while engaged: the camera looks at the fixed
1085	            // corner point, so scale by that point's distance from the corner center.
1086	            var t = MathHelper.Clamp(cornerDistance / CornerZoomReferenceDistance, 0f, 1f);
1087	            targetZoom = 1f - t * MaxZoomOut;
1088	        }
1089	        else
1090	        {
1091	            // Otherwise scale by the active red-dot's follow lag.
1092	            foreach (var entity in _activeBallTargets.GetEntities())
1093	            {
1094	                if (!entity.Get<CameraFollowTargetComponent>().IsActive) continue;
1095	                var lag = (entity.Get<TransformComponent>().Position - _camera.Position).Length();
1096	                var t = MathHelper.Clamp(lag / MaxLag, 0f, 1f);
1097	                targetZoom = 1f - t * MaxZoomOut;
1098	                break;
1099	            }
1100	        }
1101	
1102	        var smooth = 1f - (float)Math.Exp(-ZoomDamping * state.Time);
1103	        _currentZoom = MathHelper.Lerp(_currentZoom, targetZoom, smooth);
1104	        _camera.Zoom = _currentZoom;
1105	    }
1106	
1107	    public void Dispose()
1108	    {
1109	        _activeBallTargets.Dispose();
1110	        GC.SuppressFinalize(this);
1111	    }
1112	}
1113	
1114	/// Layers a short, rapid camera "hit" on top of the resolved camera transform to sell a
1115	/// "the player just took a hit" moment. When the red dot enters one of the two flanking
1116	/// hit squares — see <see cref="CameraDemoScreen.BallHitZone"/> — the system fires a burst
1117	/// of trauma on the rising edge (in any camera mode) and flashes that square yellow
1118	/// (<see cref="CameraDemoScreen.BlinkHitSquare"/>). The two squares give two distinct jolts:
1119	///
1120	/// - <b>Right square → positional shake.</b> Trauma drives a small, high-frequency random
1121	///   jitter of <c>Camera.Position</c>.
1122	/// - <b>Left square → rotational wobble.</b> Trauma drives a small, decaying cosine
1123	///   oscillation of <c>Camera.Rotation</c>.
1124	///
1125	/// Each is a separate trauma that decays to zero over a fraction of a second; magnitude
1126	/// falls off as trauma² for a sharp initial jolt that settles quickly. It is one hit per
1127	/// entry (re-enter to re-trigger), and the dot's centered spawn lies in neither square, so
1128	/// nothing fires on load.
1129	///
1130	/// It runs last in the update pipeline and writes <c>Camera.Position</c> / <c>Camera.Rotation</c>
1131	/// after <see cref="CameraFollowSystem"/> — the documented composable pattern (the camera
1132	/// overview's extension points: "write to the same Camera … last-write-wins per frame").
1133	/// To keep the jolt from bleeding into the smoothed follow path (the follow system lerps
1134	/// from <c>Camera.Position</c>), each frame it subtracts the offset and rotation it layered
1135	/// on last frame to recover the clean base, then re-applies fresh ones on top.
1136	public class CameraHitSystem : ISystem<GameState>
1137	{
1138	    // Peak positional offset in world units — kept small so the shake reads as a jolt.
1139	    private const float MaxShakeOffset = 6f;
1140	    // Peak rotation in radians (~2.9°) — a small tilt, not a roll.
1141	    private const float MaxRotation = 0.05f;
1142	    // Wobble frequency for the rotational hit — rapid (~7 Hz).
1143	    private static readonly float RotateAngularFreq = MathHelper.TwoPi * 7f;
1144	    // Trauma drains linearly to zero in 1 / TraumaDecayPerSecond seconds (~0.4s here),
1145	    // so each hit is a brief burst rather than a sustained rumble.
1146	    private const float TraumaDecayPerSecond = 2.5f;
1147	
1148	    private readonly MonoDreams.Component.Camera _camera;
1149	    private readonly CameraDemoScreen _screen;
1150	    private readonly Random _rng = new();
1151	
1152	    private Vector2 _appliedOffset = Vector2.Zero;
1153	    private float _appliedRotation;
1154	    private float _shakeTrauma;     // right square
1155	    private float _rotateTrauma;    // left square
1156	    private float _rotatePhase;     // seconds since the last left hit, for the cosine
1157	    private CameraDemoScreen.HitZone _lastZone = CameraDemoScreen.HitZone.None;
1158	
1159	    public bool IsEnabled { get; set; } = true;
1160	
1161	    public CameraHitSystem(MonoDreams.Component.Camera camera, CameraDemoScreen screen)
1162	    {
1163	        _camera = camera;
1164	        _screen = screen;
1165	    }
1166	
1167	    public void Update(GameState state)
1168	    {
1169	        if (!IsEnabled) return;
1170	
1171	        // Rising edge: the dot just entered a hit square → take a hit and flash that
1172	        // square. Right shakes, left rotates.
1173	        var zone = _screen.BallHitZone;
1174	        if (zone != CameraDemoScreen.HitZone.None && zone != _lastZone)
1175	        {
1176	            if (zone == CameraDemoScreen.HitZone.Right) _shakeTrauma = 1f;
1177	            else { _rotateTrauma = 1f; _rotatePhase = 0f; }
1178	            _screen.BlinkHitSquare(zone);
1179	        }
1180	        _lastZone = zone;
1181	
1182	        _shakeTrauma = MathHelper.Clamp(_shakeTrauma - TraumaDecayPerSecond * state.Time, 0f, 1f);
1183	        _rotateTrauma = MathHelper.Clamp(_rotateTrauma - TraumaDecayPerSecond * state.Time, 0f, 1f);
1184	        _rotatePhase += state.Time;
1185	
1186	        // Right-square shake: fresh random direction each frame → a rapid buzz, scaled by trauma².
1187	        var shakeMag = MaxShakeOffset * _shakeTrauma * _shakeTrauma;
1188	        var offset = shakeMag <= 0f
1189	            ? Vector2.Zero
1190	            : new Vector2(
1191	                (float)(_rng.NextDouble() * 2.0 - 1.0),
1192	                (float)(_rng.NextDouble() * 2.0 - 1.0)) * shakeMag;
1193	
1194	        // Left-square rotate: a decaying cosine wobble (starts at full tilt on the hit), scaled by trauma².
1195	        var angle = _rotateTrauma <= 0f
1196	            ? 0f
1197	            : MaxRotation * _rotateTrauma * _rotateTrauma * MathF.Cos(RotateAngularFreq * _rotatePhase);
1198	
1199	        // Peel off last frame's own contribution before re-applying, so neither the shake
1200	        // nor the rotation accumulates into the transform CameraFollowSystem smooths from.
1201	        _camera.Position = (_camera.Position - _appliedOffset) + offset;
1202	        _appliedOffset = offset;
1203	        _camera.Rotation = (_camera.Rotation - _appliedRotation) + angle;
1204	        _appliedRotation = angle;
1205	
1206	        _screen.UpdateHitSquareBlinks(state.Time);
1207	    }
1208	
1209	    public void Dispose() => GC.SuppressFinalize(this);
1210	}
