329	    /// Builds a nine-patch (corner = <paramref name="corner"/> px) from a finished panel sprite
330	    /// at <paramref name="r"/> on a sheet: corners kept at source size, edges + centre sampled as
331	    /// 1px strips and stretched. Lets the wide box/balloon panels scale without warping corners.
332	    private static NinePatchInfo Panel9(Rectangle r, int corner)
333	    {
334	        int x = r.X, y = r.Y, w = r.Width, h = r.Height, c = corner;
335	        return new NinePatchInfo(
336	            c,
337	            new Rectangle(x, y, c, c),                 // top-left
338	            new Rectangle(x + c, y, 1, c),             // top (stretched horizontally)
339	            new Rectangle(x + w - c, y, c, c),         // top-right
340	            new Rectangle(x, y + c, c, 1),             // left (stretched vertically)
341	            new Rectangle(x + c, y + c, 1, 1),         // centre (stretched both ways)
342	            new Rectangle(x + w - c, y + c, c, 1),     // right
343	            new Rectangle(x, y + h - c, c, c),         // bottom-left
344	            new Rectangle(x + c, y + h - c, 1, c),     // bottom
345	            new Rectangle(x + w - c, y + h - c, c, c));// bottom-right
346	    }
