568	    // ─── in-memory Yarn ──────────────────────────────────────────────────────
569	
570	    /// The conversation. Lines use Yarn's "Speaker: text" form (DialogueSystem splits the
571	    /// speaker off). `<<emote who kind>>` drives the in-box portrait (left = NPC, right =
572	    /// player); `<<react who mark>>` pops an above-head reaction mark. Both arrive as a
573	    /// DialogueCommandMessage. The start node must be named "Start" (see NpcInteractionSystem).
574	    private const string YarnSource = @"title: Start
575	---
576	<<emote npc happy>>
577	Cow: Moo! A visitor! We don't get many folks wandering out to my little meadow.
578	Cow: What brings you all the way out here, friend?
579	<<emote player question>>
580	-> I'm just exploring the area.
581	    <<emote npc happy>>
582	    Cow: Exploring! Wonderful. There's no finer patch of grass this side of the river.
583	    <<emote player happy>>
584	    <<react player star>>
585	    Player: It really is peaceful out here.
586	-> Do you ever get lonely?
587	    <<emote npc sad>>
588	    Cow: ...Sometimes. The days are long and the field is wide.
589	    <<emote npc happy>>
590	    <<react npc star>>
591	    Cow: But a good chat like this one? That keeps me going.
592	-> Wait, can cows really talk?
593	    <<emote player surprised>>
594	    <<react player question>>
595	    Player: Wait... can cows actually talk?
596	    <<emote npc surprised>>
597	    <<react npc exclaim>>
598	    Cow: Can't yours?
599	    <<emote player surprised>>
600	    Player: ...Fair enough.
601	<<emote npc happy>>
602	Cow: Do come visit again. The meadow's always right here.
603	<<react npc star>>
604	===
605	";
606	
607	    /// Compiles a Yarn source string into a runtime <see cref="YarnProgram"/>, mirroring
608	    /// what <c>YarnSpinnerProcessor</c> does at content-build time — so the demo ships no
609	    /// .yarn asset. The required deps (Yarn.Compiler, Google.Protobuf, CsvHelper) flow in
610	    /// transitively from MonoDreams.
611	    private static YarnProgram CompileYarn(string source)
612	    {
613	        var job = CompilationJob.CreateFromString("DemoDialogue", source);
614	        var result = Compiler.Compile(job);
615	        if (result.Program == null)
616	            throw new InvalidOperationException(
617	                "Demo Yarn script failed to compile: " + string.Join("; ", result.Diagnostics));
618	
619	        var program = new YarnProgram();
620	
621	        using (var memoryStream = new MemoryStream())
622	        using (var outputStream = new CodedOutputStream(memoryStream))
623	        {
624	            result.Program.WriteTo(outputStream);
625	            outputStream.Flush();
626	            program.CompiledProgram = memoryStream.ToArray();
627	        }
628	
629	        using (var memoryStream = new MemoryStream())
630	        {
631	            using var textWriter = new StreamWriter(memoryStream);
632	            var csv = new CsvWriter(textWriter, new CsvConfiguration(CultureInfo.InvariantCulture));
633	            var lines = result.StringTable!.Select(x => new
634	            {
635	                id = x.Key,
636	                text = x.Value.text,
637	                file = x.Value.fileName,
638	                node = x.Value.nodeName,
639	                lineNumber = x.Value.lineNumber,
640	            });
641	            csv.WriteRecords(lines);
642	            textWriter.Flush();
643	            memoryStream.Position = 0;
644	            using var reader = new StreamReader(memoryStream);
645	            program.BaseLocalizationId = CultureInfo.CurrentCulture.Name;
646	            program.BaseLocalisationStringTable = reader.ReadToEnd();
647	            program.Localizations = new YarnTranslation[0];
648	        }
649	
650	        return program;
651	    }
652	}
