688	        _spriteHeight = spriteHeight;
689	        _isFrozen = isFrozen;
690	    }
691	
692	    protected override void Update(GameState state, in Entity entity)
693	    {
694	        ref var sprite = ref entity.Get<SpriteInfoComponent>();
695	
696	        if (_isFrozen())
697	        {
698	            _frame = 0;
699	            _animTimer = 0f;
700	            sprite.Source = new Rectangle(0, 0, _sourceFrame, _sourceFrame);
701	            return;
702	        }
703	
704	        var keyboard = Keyboard.GetState();
705	        var dir = Vector2.Zero;
706	        if (keyboard.IsKeyDown(Keys.A) || keyboard.IsKeyDown(Keys.Left)) dir.X -= 1f;
707	        if (keyboard.IsKeyDown(Keys.D) || keyboard.IsKeyDown(Keys.Right)) dir.X += 1f;
708	        if (keyboard.IsKeyDown(Keys.W) || keyboard.IsKeyDown(Keys.Up)) dir.Y -= 1f;
709	        if (keyboard.IsKeyDown(Keys.S) || keyboard.IsKeyDown(Keys.Down)) dir.Y += 1f;
710	
711	        var transform = entity.Get<TransformComponent>();
712	
713	        if (dir != Vector2.Zero)
714	        {
715	            dir.Normalize();
716	            var next = transform.Position + dir * _speed * state.Time;
717	            // Feet anchored at the position; keep the whole rendered sprite inside the boundary.
718	            next.X = MathHelper.Clamp(next.X, -_halfWidth + _spriteHalfWidth, _halfWidth - _spriteHalfWidth);
719	            next.Y = MathHelper.Clamp(next.Y, -_halfHeight + _spriteHeight, _halfHeight);
720	            transform.Position = next;
721	
722	            _animTimer += state.Time;
723	            if (_animTimer >= BobInterval)
724	            {
725	                _animTimer = 0f;
726	                _frame ^= 1; // toggle between the first two front-facing frames
727	            }
728	        }
729	        else
730	        {
731	            _frame = 0;
732	            _animTimer = 0f;
733	        }
734	
735	        sprite.Source = new Rectangle(_frame * _sourceFrame, 0, _sourceFrame, _sourceFrame);
736	    }
737	}
