739	/// Shows a "press E" prompt when the player is near the NPC and, on the interact edge,
740	/// publishes a <see cref="DialogueStartMessage"/>. Suppressed while a dialogue is active.
741	public sealed class NpcInteractionSystem : ISystem<GameState>
742	{
743	    private readonly Entity _player;
744	    private readonly Entity _npc;
745	    private readonly Entity _prompt;
746	    private readonly AInputState _interact;
747	    private readonly float _rangeSq;
748	    private readonly Func<bool> _dialogueActive;
749	    private readonly World _world;
750	
751	    public bool IsEnabled { get; set; } = true;
752	
753	    public NpcInteractionSystem(World world, Entity player, Entity npc, Entity prompt,
754	        AInputState interact, float range, Func<bool> dialogueActive)
755	    {
756	        _world = world;
757	        _player = player;
758	        _npc = npc;
759	        _prompt = prompt;
760	        _interact = interact;
761	        _rangeSq = range * range;
762	        _dialogueActive = dialogueActive;
763	    }
764	
765	    public void Update(GameState state)
766	    {
767	        if (!IsEnabled || !_player.IsAlive || !_npc.IsAlive) return;
768	
769	        if (_dialogueActive())
770	        {
771	            SetPromptVisible(false);
772	            return;
773	        }
774	
775	        var playerPos = _player.Get<TransformComponent>().Position;
776	        var npcPos = _npc.Get<TransformComponent>().Position;
777	        var inRange = Vector2.DistanceSquared(playerPos, npcPos) <= _rangeSq;
778	
779	        SetPromptVisible(inRange);
780	
781	        if (inRange && _interact.JustPressed())
782	            _world.Publish(new DialogueStartMessage(_npc, "Start"));
783	    }
784	
785	    private void SetPromptVisible(bool visible)
786	    {
787	        if (!_prompt.IsAlive) return;
788	        var has = _prompt.Has<VisibleComponent>();
789	        if (visible && !has) _prompt.Set<VisibleComponent>();
790	        else if (!visible && has) _prompt.Remove<VisibleComponent>();
791	    }
792	
793	    public void Dispose() => GC.SuppressFinalize(this);
794	}
