800	/// Above-head reaction marks. Subscribes to <see cref="DialogueCommandMessage"/>, reacts to
801	/// `react who mark` by showing an icon (from all_icons) above the player or cow on the Main
802	/// target, and auto-hides it after a delay. Clears on dialogue end.
803	public sealed class ReactionMarkSystem : ISystem<GameState>
804	{
805	    private readonly Entity _playerMark;
806	    private readonly Entity _npcMark;
807	    private readonly Dictionary<string, Rectangle> _icons;
808	    private readonly float _duration;
809	
810	    public bool IsEnabled { get; set; } = true;
811	
812	    public ReactionMarkSystem(World world, Entity playerMark, Entity npcMark,
813	        Dictionary<string, Rectangle> icons, float duration)
814	    {
815	        _playerMark = playerMark;
816	        _npcMark = npcMark;
817	        _icons = icons;
818	        _duration = duration;
819	        world.Subscribe(this);
820	    }
821	
822	    [Subscribe]
823	    private void OnCommand(in DialogueCommandMessage msg)
824	    {
825	        var parts = msg.Command.Split(' ', StringSplitOptions.RemoveEmptyEntries);
826	        if (parts.Length < 3 || parts[0] != "react") return;
827	
828	        var target = parts[1] switch
829	        {
830	            "player" => _playerMark,
831	            "npc" => _npcMark,
832	            _ => default,
833	        };
834	        if (!target.IsAlive || !_icons.TryGetValue(parts[2], out var cell)) return;
835	
836	        target.Set(new EmoteBubbleComponent { HideAt = float.NaN });
837	        if (!target.Has<VisibleComponent>()) target.Set<VisibleComponent>();
838	        ref var sprite = ref target.Get<SpriteInfoComponent>();
839	        sprite.Source = cell;
840	    }
841	
842	    [Subscribe]
843	    private void OnDialogueActive(in DialogueActiveMessage msg)
844	    {
845	        if (!msg.IsActive)
846	        {
847	            Hide(_playerMark);
848	            Hide(_npcMark);
849	        }
850	    }
851	
852	    public void Update(GameState state)
853	    {
854	        Expire(_playerMark, state.TotalTime);
855	        Expire(_npcMark, state.TotalTime);
856	    }
857	
858	    private void Expire(Entity mark, float now)
859	    {
860	        if (!mark.IsAlive || !mark.Has<EmoteBubbleComponent>()) return;
861	        ref var bubble = ref mark.Get<EmoteBubbleComponent>();
862	        if (float.IsNaN(bubble.HideAt)) { bubble.HideAt = now + _duration; return; }
863	        if (now >= bubble.HideAt) Hide(mark);
864	    }
865	
866	    // Main-target child — removing VisibleComponent is enough to hide it.
867	    private static void Hide(Entity mark)
868	    {
869	        if (!mark.IsAlive) return;
870	        if (mark.Has<VisibleComponent>()) mark.Remove<VisibleComponent>();
871	        if (mark.Has<EmoteBubbleComponent>()) mark.Remove<EmoteBubbleComponent>();
872	    }
873	
874	    public void Dispose() => GC.SuppressFinalize(this);
875	}
876	
877	/// In-box speaker portrait. Subscribes to <see cref="DialogueCommandMessage"/>; on
878	/// `emote who kind` it shows the framed portrait of whoever is speaking in the single emote
879	/// frame (the box's left gutter). The NPC uses the cow's own head (a fixed crop — the cow has
880	/// no expression frames, so `kind` is ignored there); the player picks an emote face by `kind`.
881	/// The portrait persists until the next `emote` or the dialogue ends — it does not auto-expire
882	/// (unlike reaction marks). Frame + face live on the UI target, which always renders, so hiding
883	/// clears the drawable (the sprite's sheet + texture) rather than toggling VisibleComponent.
884	public sealed class DialoguePortraitSystem : ISystem<GameState>
885	{
886	    private readonly PortraitSlot _slot;
887	    private readonly Texture2D _frameSheet;
888	    private readonly Rectangle _frameSource;    // the ornate wood frame (static, shown on any emote)
889	    private readonly Texture2D _cowSheet;
890	    private readonly Rectangle _cowSource;      // the cow's head crop (same for every kind)
891	    private readonly Texture2D _emoteSheet;
892	    private readonly Dictionary<string, Rectangle> _emoteCells;
893	
894	    public bool IsEnabled { get; set; } = true;
895	
896	    public DialoguePortraitSystem(World world, PortraitSlot slot,
897	        Texture2D frameSheet, Rectangle frameSource,
898	        Texture2D cowSheet, Rectangle cowSource,
899	        Texture2D emoteSheet, Dictionary<string, Rectangle> emoteCells)
900	    {
901	        _slot = slot;
902	        _frameSheet = frameSheet;
903	        _frameSource = frameSource;
904	        _cowSheet = cowSheet;
905	        _cowSource = cowSource;
906	        _emoteSheet = emoteSheet;
907	        _emoteCells = emoteCells;
908	        world.Subscribe(this);
909	    }
910	
911	    [Subscribe]
912	    private void OnCommand(in DialogueCommandMessage msg)
913	    {
914	        var parts = msg.Command.Split(' ', StringSplitOptions.RemoveEmptyEntries);
915	        if (parts.Length < 3 || parts[0] != "emote") return;
916	
917	        switch (parts[1])
918	        {
919	            case "npc":
920	                ShowFace(_cowSheet, _cowSource); // the cow's head, regardless of kind
921	                break;
922	            case "player":
923	                if (_emoteCells.TryGetValue(parts[2], out var cell)) ShowFace(_emoteSheet, cell);
924	                break;
925	        }
926	    }
927	
928	    [Subscribe]
929	    private void OnDialogueActive(in DialogueActiveMessage msg)
930	    {
931	        if (!msg.IsActive)
932	        {
933	            ClearSprite(_slot.Frame);
934	            ClearSprite(_slot.Face);
935	        }
936	    }
937	
938	    public void Update(GameState state) { }
939	
940	    private void ShowFace(Texture2D sheet, Rectangle source)
941	    {
942	        // Show the (static) wood frame on the first emote, then swap in the speaker's face.
943	        if (_slot.Frame.IsAlive)
944	        {
945	            ref var frameSprite = ref _slot.Frame.Get<SpriteInfoComponent>();
946	            frameSprite.SpriteSheet = _frameSheet;
947	            frameSprite.Source = _frameSource;
948	        }
949	        if (_slot.Face.IsAlive)
950	        {
951	            ref var faceSprite = ref _slot.Face.Get<SpriteInfoComponent>();
952	            faceSprite.SpriteSheet = sheet;
953	            faceSprite.Source = source;
954	        }
955	    }
956	
957	    private static void ClearSprite(Entity e)
958	    {
959	        if (!e.IsAlive) return;
960	        ref var sprite = ref e.Get<SpriteInfoComponent>();
961	        sprite.SpriteSheet = null;              // SpritePrep skips it
962	        e.Get<DrawComponent>().Texture = null;  // and don't draw the stale texture
963	    }
964	
965	    public void Dispose() => GC.SuppressFinalize(this);
966	}
