985	/// Edge-triggered screen shortcuts: R resets the player, Escape returns to the launcher.
986	public sealed class DialogueDemoShortcutSystem : ISystem<GameState>
987	{
988	    private readonly DialogueDemoScreen _screen;
989	    private KeyboardState _previous;
990	    public bool IsEnabled { get; set; } = true;
991	
992	    public DialogueDemoShortcutSystem(DialogueDemoScreen screen)
993	    {
994	        _screen = screen;
995	        _previous = Keyboard.GetState();
996	    }
997	
998	    public void Update(GameState state)
999	    {
1000	        if (!IsEnabled) return;
1001	        var current = Keyboard.GetState();
1002	        bool Pressed(Keys k) => current.IsKeyDown(k) && !_previous.IsKeyDown(k);
1003	
1004	        if (Pressed(Keys.R)) _screen.ResetPlayer();
1005	        if (Pressed(Keys.Escape)) _screen.GoBackToLauncher();
1006	
1007	        _previous = current;
1008	    }
1009	
1010	    public void Dispose() => GC.SuppressFinalize(this);
1011	}
