17	public class DialogueSystem : ISystem<GameState>
18	{
19	    private readonly World _world;
20	    private readonly Entity _rootEntity;
21	    private readonly DialogueStateComponent _dialogueState;
22	    private readonly BitmapFont _font;
23	    private readonly TransformComponent _rootTransform;
24	    private readonly float _layerDepth;
25	    private readonly string _entityInfoType;
26	    private readonly AInputState _interact;
27	    private readonly AInputState _up;
28	    private readonly AInputState _down;
29	
30	    // Set when a Yarn <<command>> fires mid-conversation. The post-command Continue() is
31	    // deferred to the next Update (see Update) rather than called re-entrantly inside the
32	    // Yarn command handler, which would risk faulting the VM.
33	    private bool _pendingContinue;
34	
35	    // Text layout (computed in the constructor, used by line + option rendering).
36	    private readonly float _textScale;
37	    private readonly Vector2 _textLocalPos; // UI-local top-left where the line text + options start
38	    private readonly float _textAreaWidth;
39	    private readonly float _overlayDepth;
40	
41	    // Balloon mode (optional): an inner "talk balloon" panel that wraps the text, with a left
42	    // gutter reserved for a game-drawn emote/portrait frame. When off, the legacy box + symmetric
43	    // sideInset layout is used. Activated by passing a talkBalloonTexture (see the constructor).
44	    private readonly bool _balloonMode;
45	    private readonly Entity _balloonEntity;
46	
47	    /// UI-space rectangle of the left portrait gutter — the box's left region reserved for a
48	    /// game-drawn emote frame — when balloon mode is active; <see cref="Rectangle.Empty"/> otherwise.
49	    public Rectangle PortraitGutterBounds { get; }
50	
51	    // Yarn runtime
52	    private readonly Yarn.Dialogue _yarnDialogue;
53	    private readonly DialogueRunner _dialogueRunner;
54	    private readonly InMemoryVariableStorage _variableStorage;
55	
56	    public bool IsEnabled { get; set; } = true;
57	
58	    public DialogueSystem(
59	        World world,
60	        Texture2D dialogBoxTexture,
61	        BitmapFont font,
62	        Texture2D indicatorTexture,
63	        int virtualWidth,
64	        int virtualHeight,
65	        float layerDepth,
66	        AInputState interact,
67	        AInputState up,
68	        AInputState down,
69	        YarnProgram[] yarnPrograms,
70	        string entityInfoType = "Dialogue",
71	        float textScale = 0.32f,
72	        float sideInset = 0f,
73	        float indicatorSize = 44f,
74	        Texture2D? talkBalloonTexture = null,
75	        NinePatchInfo? talkBalloonNinePatch = null,
76	        float portraitGutter = 0f,
77	        float balloonPadding = 12f,
78	        float boxHeight = 120f,
79	        NinePatchInfo? boxNinePatch = null)
80	    {
81	        _world = world;
82	        _font = font;
83	        _layerDepth = layerDepth;
84	        _entityInfoType = entityInfoType;
85	        _interact = interact;
86	        _up = up;
87	        _down = down;
88	        _textScale = textScale;
89	        world.Subscribe(this);
90	
91	        var overlayDepth = layerDepth + 0.01f;
92	        _overlayDepth = overlayDepth;
93	
94	        // Layout constants (UI coordinates, virtual resolution). The box fills the screen width
95	        // minus a margin and sits at the bottom.
96	        const float boxMargin = 20f;
97	        var boxWidth = virtualWidth - 2f * boxMargin;
98	        var rootPosition = new Vector2(boxMargin, virtualHeight - boxHeight - boxMargin);
99	
100	        _balloonMode = talkBalloonTexture != null;
101	
102	        // Where the line text + options start, the text wrap width, and the continue indicator,
103	        // differ between balloon mode (text lives inside an inner panel, left gutter reserved for
104	        // a game-drawn emote frame) and legacy mode (text on the box, symmetric sideInset).
105	        Vector2 textLocal;
106	        Vector2 indicatorOffset;
107	        float balloonX = 0f, balloonY = 0f, balloonW = 0f, balloonH = 0f;
108	        if (_balloonMode)
109	        {
110	            const float vMargin = 10f;   // balloon inset from the box top/bottom
111	            const float rightMargin = 16f; // balloon inset from the box right edge
112	            balloonX = portraitGutter;
113	            balloonY = vMargin;
114	            balloonW = boxWidth - portraitGutter - rightMargin;
115	            balloonH = boxHeight - 2f * vMargin;
116	            textLocal = new Vector2(balloonX + balloonPadding, balloonY + balloonPadding);
117	            _textAreaWidth = balloonW - 2f * balloonPadding;
118	            indicatorOffset = new Vector2(
119	                balloonX + balloonW - indicatorSize - 10f,
120	                balloonY + balloonH - indicatorSize - 8f);
121	            // UI-space rect of the left gutter, for the demo to place its emote frame.
122	            PortraitGutterBounds = new Rectangle(
123	                (int)rootPosition.X, (int)rootPosition.Y, (int)portraitGutter, (int)boxHeight);
124	        }
125	        else
126	        {
127	            var textOffset = new Vector2(16, 16);
128	            // Line + option text wrap within the box minus symmetric side insets — the insets
129	            // reserve room on each side for a game-drawn portrait (see sideInset).
130	            textLocal = new Vector2(textOffset.X + sideInset, textOffset.Y);
131	            _textAreaWidth = boxWidth - 2f * textOffset.X - 2f * sideInset;
132	            // Continue marker sits at the bottom-right of the TEXT area (inset past any portrait).
133	            indicatorOffset = new Vector2(boxWidth - sideInset - indicatorSize - 12, boxHeight - indicatorSize - 8);
134	            PortraitGutterBounds = Rectangle.Empty;
135	        }
136	        _textLocalPos = textLocal;
137	
138	        // Create root entity
139	        _rootTransform = new TransformComponent(rootPosition);
140	        _rootEntity = world.CreateEntity();
141	        _rootEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueRoot"));
142	        _rootEntity.Set(_rootTransform);
143	        _dialogueState = new DialogueStateComponent();
144	        _rootEntity.Set(_dialogueState);
145	
146	        // Create box child entity
147	        _dialogueState.BoxEntity = world.CreateEntity();
148	        _dialogueState.BoxEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueBox"));
149	        _dialogueState.BoxEntity.Set(new TransformComponent());
150	        _dialogueState.BoxEntity.SetParent(_rootEntity);
151	        _dialogueState.BoxEntity.Set(new SpriteInfoComponent
152	        {
153	            SpriteSheet = dialogBoxTexture,
154	            Source = new Rectangle(0, 0, dialogBoxTexture.Width, dialogBoxTexture.Height),
155	            Size = new Vector2(boxWidth, boxHeight),
156	            Color = Color.White,
157	            Target = RenderTargetID.UI,
158	            LayerDepth = _layerDepth,
159	            // Default nine-patch suits the 128×48 "dialog box medium" art; pass boxNinePatch to
160	            // back the box with a different panel texture.
161	            NinePatchData = boxNinePatch ?? new NinePatchInfo(
162	                23,
163	                new Rectangle(0, 0, 23, 23),
164	                new Rectangle(23, 0, 1, 23),
165	                new Rectangle(24, 0, 23, 23),
166	                new Rectangle(0, 23, 23, 1),
167	                new Rectangle(23, 23, 1, 1),
168	                new Rectangle(24, 23, 23, 1),
169	                new Rectangle(0, 24, 23, 23),
170	                new Rectangle(23, 24, 1, 23),
171	                new Rectangle(24, 24, 23, 23))
172	        });
173	        _dialogueState.BoxEntity.Set(new DrawComponent
174	        {
175	            Type = DrawElementType.Sprite,
176	            Target = RenderTargetID.UI
177	        });
178	
179	        // Create inner talk-balloon child (balloon mode only): a nine-patch panel that holds the
180	        // text/options/indicator, drawn just above the box and beside the left portrait gutter.
181	        if (_balloonMode)
182	        {
183	            _balloonEntity = world.CreateEntity();
184	            _balloonEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueBalloon"));
185	            _balloonEntity.Set(new TransformComponent(new Vector2(balloonX, balloonY)));
186	            _balloonEntity.SetParent(_rootEntity);
187	            _balloonEntity.Set(new SpriteInfoComponent
188	            {
189	                SpriteSheet = talkBalloonTexture,
190	                Source = new Rectangle(0, 0, talkBalloonTexture!.Width, talkBalloonTexture.Height),
191	                Size = new Vector2(balloonW, balloonH),
192	                Color = Color.White,
193	                Target = RenderTargetID.UI,
194	                LayerDepth = _layerDepth + 0.005f, // between the box and the text/options
195	                NinePatchData = talkBalloonNinePatch,
196	            });
197	            _balloonEntity.Set(new DrawComponent
198	            {
199	                Type = DrawElementType.Sprite,
200	                Target = RenderTargetID.UI
201	            });
202	        }
203	
204	        // Create text child entity
205	        _dialogueState.TextEntity = world.CreateEntity();
206	        _dialogueState.TextEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueText"));
207	        _dialogueState.TextEntity.Set(new TransformComponent(_textLocalPos));
208	        _dialogueState.TextEntity.SetParent(_rootEntity);
209	        _dialogueState.TextEntity.Set(new DynamicTextComponent
210	        {
211	            Target = RenderTargetID.UI,
212	            LayerDepth = overlayDepth,
213	            Font = _font,
214	            Color = Color.SaddleBrown,
215	            Scale = textScale,
216	            RevealingSpeed = 20,
217	            RevealStartTime = float.NaN,
218	            IsRevealed = false,
219	            VisibleCharacterCount = 0,
220	            TextContent = ""
221	        });
222	        _dialogueState.TextEntity.Set(new DrawComponent
223	        {
224	            Type = DrawElementType.Text,
225	            Target = RenderTargetID.UI
226	        });
227	
228	        // Create indicator child entity
229	        _dialogueState.IndicatorEntity = world.CreateEntity();
230	        _dialogueState.IndicatorEntity.Set(new EntityInfoComponent(_entityInfoType, "DialogueIndicator"));
231	        _dialogueState.IndicatorEntity.Set(new TransformComponent(indicatorOffset));
232	        _dialogueState.IndicatorEntity.SetParent(_rootEntity);
233	        _dialogueState.IndicatorEntity.Set(new SpriteInfoComponent
234	        {
235	            SpriteSheet = indicatorTexture,
236	            Source = new Rectangle(0, 0, indicatorTexture.Width, indicatorTexture.Height),
237	            Size = new Vector2(indicatorSize, indicatorSize),
238	            Color = Color.White,
239	            Target = RenderTargetID.UI,
240	            LayerDepth = overlayDepth
241	        });
242	        _dialogueState.IndicatorEntity.Set(new DrawComponent
243	        {
244	            Type = DrawElementType.Sprite,
245	            Target = RenderTargetID.UI
246	        });
247	
248	        // Set up Yarn runtime
249	        _dialogueRunner = new DialogueRunner();
250	        _variableStorage = new InMemoryVariableStorage();
251	        _yarnDialogue = new Yarn.Dialogue(_variableStorage)
252	        {
253	            LogDebugMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn] {msg}"),
254	            LogErrorMessage = msg => global::System.Diagnostics.Debug.WriteLine($"[Yarn ERROR] {msg}"),
255	            LineHandler = OnYarnLine,
256	            OptionsHandler = OnYarnOptions,
257	            CommandHandler = OnYarnCommand,
258	            NodeStartHandler = OnYarnNodeStart,
259	            NodeCompleteHandler = OnYarnNodeComplete,
260	            DialogueCompleteHandler = OnYarnDialogueComplete,
261	        };
262	
263	        // Combine all yarn programs via protobuf merge
264	        Yarn.Program combinedProgram = null;
265	        foreach (var yarnProgram in yarnPrograms)
266	        {
267	            _dialogueRunner.AddStringTable(yarnProgram);
268	            var program = yarnProgram.GetProgram();
269	            if (combinedProgram == null)
270	            {
271	                combinedProgram = program;
272	            }
273	            else
274	            {
275	                combinedProgram.MergeFrom(program);
276	            }
277	        }
278	        _yarnDialogue.SetProgram(combinedProgram);
279	    }
280	
281	    // --- Yarn callbacks (fire synchronously during Continue()) ---
282	
283	    private void OnYarnLine(Line line)
284	    {
285	        var text = _dialogueRunner.GetLocalizedTextForLine(line);
286	
287	        // Parse "Speaker: text" format
288	        string speaker = null;
289	        var displayText = text;
290	        var colonIndex = text.IndexOf(':');
291	        if (colonIndex > 0 && colonIndex < 30)
292	        {
293	            speaker = text[..colonIndex].Trim();
294	            displayText = text[(colonIndex + 1)..].Trim();
295	        }
296	
297	        // Wrap so long lines break onto new lines instead of overflowing the box. The reveal
298	        // animation slices the wrapped string, so embedded newlines just advance instantly.
299	        displayText = WrapText(displayText, _textAreaWidth);
300	
301	        _dialogueState.CurrentPhase = DialoguePhase.Line;
302	        _dialogueState.CurrentSpeaker = speaker;
303	        _dialogueState.WaitingForInput = false;
304	
305	        // Set text content and reset reveal animation
306	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
307	        dynamicText.TextContent = displayText;
308	        dynamicText.VisibleCharacterCount = 0;
309	        dynamicText.IsRevealed = false;
310	        dynamicText.RevealStartTime = float.NaN;
311	
312	        HideIndicator();
313	        HideOptions();
314	    }
315	
316	    private void OnYarnOptions(OptionSet optionSet)
317	    {
318	        _dialogueState.CurrentPhase = DialoguePhase.Options;
319	        _dialogueState.CurrentOptions.Clear();
320	        _dialogueState.CurrentOptionIDs.Clear();
321	        _dialogueState.SelectedOptionIndex = 0;
322	        _dialogueState.WaitingForInput = true;
323	
324	        foreach (var option in optionSet.Options)
325	        {
326	            if (!option.IsAvailable) continue;
327	            var text = _dialogueRunner.GetLocalizedTextForLine(option.Line);
328	            _dialogueState.CurrentOptions.Add(text);
329	            _dialogueState.CurrentOptionIDs.Add(option.ID);
330	        }
331	
332	        // Clear the main text line
333	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
334	        dynamicText.TextContent = "";
335	        dynamicText.VisibleCharacterCount = 0;
336	
337	        ShowOptions();
338	        HideIndicator();
339	    }
340	
341	    private void OnYarnCommand(Command command)
342	    {
343	        global::System.Diagnostics.Debug.WriteLine($"[Yarn Command] {command.Text}");
344	        // Surface the command so game code can react (emotes, SFX, flags), then flag the
345	        // conversation to flow past it on the next Update — see _pendingContinue.
346	        _world.Publish(new DialogueCommandMessage(command.Text));
347	        _pendingContinue = true;
348	    }
349	
350	    private void OnYarnNodeStart(string nodeName)
351	    {
352	        global::System.Diagnostics.Debug.WriteLine($"[Yarn] Node started: {nodeName}");
353	    }
354	
355	    private void OnYarnNodeComplete(string nodeName)
356	    {
357	        global::System.Diagnostics.Debug.WriteLine($"[Yarn] Node complete: {nodeName}");
358	    }
359	
360	    private void OnYarnDialogueComplete()
361	    {
362	        _dialogueState.CurrentPhase = DialoguePhase.Complete;
363	        DeactivateDialogue();
364	    }
365	
366	    // --- Dialogue start trigger ---
367	
368	    [Subscribe]
369	    private void OnDialogueStart(in DialogueStartMessage message)
370	    {
371	        if (_dialogueState.IsActive) return;
372	        StartYarnDialogue(message.StartNode);
373	    }
374	
375	    public void StartYarnDialogue(string nodeName)
376	    {
377	        _dialogueState.IsActive = true;
378	        _dialogueState.WasTriggered = true;
379	
380	        // The Interact press that opened this dialogue may still be held this same
381	        // frame. Consume the edge so DialogueSystem.Update (later in this tick)
382	        // doesn't read JustPressed and advance the first line on its own opening.
383	        _interact.Consume();
384	
385	        // Show dialogue box (and inner balloon, if any). VisibleComponent gates SpritePrepSystem,
386	        // which fills the nine-patch texture, so both panels need it set to render.
387	        _dialogueState.BoxEntity.Set<VisibleComponent>();
388	        if (_balloonMode) _balloonEntity.Set<VisibleComponent>();
389	
390	        _world.Publish(new DialogueActiveMessage(true));
391	
392	        // Start the yarn node — fires LineHandler or OptionsHandler synchronously
393	        _yarnDialogue.SetNode(nodeName);
394	        _yarnDialogue.Continue();
395	    }
396	
397	    // --- Update loop ---
398	
399	    public void Update(GameState state)
400	    {
401	        if (!_dialogueState.IsActive) return;
402	
403	        // A <<command>> fired during the previous Continue(). Advance past it now, outside
404	        // the Yarn handler, so an inline command (e.g. <<emote ...>>) doesn't stall the line.
405	        if (_pendingContinue)
406	        {
407	            _pendingContinue = false;
408	            _yarnDialogue.Continue();
409	            if (!_dialogueState.IsActive) return; // command was the last thing before ===
410	        }
411	
412	        switch (_dialogueState.CurrentPhase)
413	        {
414	            case DialoguePhase.Line:
415	                UpdateLinePhase(_interact.JustPressed());
416	                break;
417	            case DialoguePhase.Options:
418	                UpdateOptionsPhase(
419	                    _up.JustPressed(),
420	                    _down.JustPressed(),
421	                    _interact.JustPressed());
422	                break;
423	        }
424	    }
425	
426	    private void UpdateLinePhase(bool interactJustPressed)
427	    {
428	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
429	
430	        if (dynamicText.IsRevealed)
431	        {
432	            if (!_dialogueState.IndicatorEntity.Has<VisibleComponent>())
433	                _dialogueState.IndicatorEntity.Set<VisibleComponent>();
434	            _dialogueState.WaitingForInput = true;
435	        }
436	        else
437	        {
438	            HideIndicator();
439	        }
440	
441	        if (!interactJustPressed) return;
442	
443	        if (!dynamicText.IsRevealed)
444	        {
445	            // Skip reveal — show all text immediately
446	            dynamicText.VisibleCharacterCount = dynamicText.TextContent?.Length ?? 0;
447	            dynamicText.IsRevealed = true;
448	        }
449	        else
450	        {
451	            // Advance to next yarn content
452	            _yarnDialogue.Continue();
453	        }
454	    }
455	
456	    private void UpdateOptionsPhase(bool upJustPressed, bool downJustPressed, bool interactJustPressed)
457	    {
458	        if (upJustPressed)
459	        {
460	            _dialogueState.SelectedOptionIndex =
461	                Math.Max(0, _dialogueState.SelectedOptionIndex - 1);
462	            UpdateOptionHighlights();
463	        }
464	        else if (downJustPressed)
465	        {
466	            _dialogueState.SelectedOptionIndex =
467	                Math.Min(_dialogueState.CurrentOptions.Count - 1, _dialogueState.SelectedOptionIndex + 1);
468	            UpdateOptionHighlights();
469	        }
470	
471	        if (interactJustPressed)
472	        {
473	            var yarnOptionID = _dialogueState.CurrentOptionIDs[_dialogueState.SelectedOptionIndex];
474	            HideOptions();
475	            _yarnDialogue.SetSelectedOption(yarnOptionID);
476	            _yarnDialogue.Continue();
477	        }
478	    }
479	
480	    // --- Option entity management ---
481	
482	    private void ShowOptions()
483	    {
484	        HideOptions();
485	
486	        // Match the multi-line render advance (Font.LineHeight * scale * leading) so wrapped
487	        // options stack without overlap — see DynamicTextComponent.DefaultLineSpacing.
488	        var lineHeight = _font.LineHeight * _textScale * DynamicTextComponent.DefaultLineSpacing;
489	        var gap = lineHeight * 0.4f;
490	        var x = _textLocalPos.X;
491	        var y = _textLocalPos.Y;
492	
493	        for (var i = 0; i < _dialogueState.CurrentOptions.Count; i++)
494	        {
495	            var fullText = OptionDisplay(i);
496	
497	            var optionEntity = _world.CreateEntity();
498	            optionEntity.Set(new EntityInfoComponent(_entityInfoType, $"DialogueOption{i}"));
499	            optionEntity.Set(new TransformComponent(new Vector2(x, y)));
500	            optionEntity.SetParent(_rootEntity);
501	            optionEntity.Set(new DynamicTextComponent
502	            {
503	                Target = RenderTargetID.UI,
504	                LayerDepth = _overlayDepth,
505	                Font = _font,
506	                Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown,
507	                Scale = _textScale,
508	                RevealingSpeed = 0, // Instant reveal
509	                RevealStartTime = 0,
510	                IsRevealed = true,
511	                VisibleCharacterCount = fullText.Length,
512	                TextContent = fullText
513	            });
514	            optionEntity.Set(new DrawComponent
515	            {
516	                Type = DrawElementType.Text,
517	                Target = RenderTargetID.UI
518	            });
519	            optionEntity.Set<VisibleComponent>();
520	
521	            _dialogueState.OptionEntities.Add(optionEntity);
522	
523	            // Advance by this option's wrapped height so multi-line options never overlap.
524	            var lines = CountLines(fullText);
525	            y += lines * lineHeight + gap;
526	        }
527	    }
528	
529	    private void UpdateOptionHighlights()
530	    {
531	        for (var i = 0; i < _dialogueState.OptionEntities.Count; i++)
532	        {
533	            var entity = _dialogueState.OptionEntities[i];
534	            if (!entity.IsAlive) continue;
535	
536	            ref var dt = ref entity.Get<DynamicTextComponent>();
537	            // The font is monospace and the "> "/"  " prefix is a fixed width, so re-wrapping
538	            // here can't change line count — option positions stay put across selection moves.
539	            dt.TextContent = OptionDisplay(i);
540	            dt.VisibleCharacterCount = dt.TextContent.Length;
541	            dt.Color = i == _dialogueState.SelectedOptionIndex ? Color.White : Color.SaddleBrown;
542	        }
543	    }
544	
545	    /// The selection-prefixed, wrapped text for option <paramref name="i"/>.
546	    private string OptionDisplay(int i)
547	    {
548	        var prefix = i == _dialogueState.SelectedOptionIndex ? "> " : "  ";
549	        var prefixWidth = _font.MeasureString(prefix).Width * _textScale;
550	        var wrapped = WrapText(_dialogueState.CurrentOptions[i], _textAreaWidth - prefixWidth);
551	        return prefix + wrapped;
552	    }
553	
554	    private static int CountLines(string text)
555	    {
556	        if (string.IsNullOrEmpty(text)) return 1;
557	        var n = 1;
558	        foreach (var c in text) if (c == '\n') n++;
559	        return n;
560	    }
561	
562	    /// Greedy word-wrap to <paramref name="maxWidth"/> rendered pixels (font measured at
563	    /// <see cref="_textScale"/>), inserting newlines. A single word wider than maxWidth is
564	    /// left on its own line rather than split.
565	    private string WrapText(string text, float maxWidth)
566	    {
567	        if (string.IsNullOrEmpty(text) || maxWidth <= 0) return text;
568	
569	        var result = new StringBuilder();
570	        var line = new StringBuilder();
571	        foreach (var word in text.Split(' ', StringSplitOptions.RemoveEmptyEntries))
572	        {
573	            var candidate = line.Length == 0 ? word : line + " " + word;
574	            if (line.Length > 0 && _font.MeasureString(candidate).Width * _textScale > maxWidth)
575	            {
576	                if (result.Length > 0) result.Append('\n');
577	                result.Append(line);
578	                line.Clear();
579	                line.Append(word);
580	            }
581	            else
582	            {
583	                if (line.Length > 0) line.Append(' ');
584	                line.Append(word);
585	            }
586	        }
587	        if (line.Length > 0)
588	        {
589	            if (result.Length > 0) result.Append('\n');
590	            result.Append(line);
591	        }
592	        return result.ToString();
593	    }
594	
595	    private void HideOptions()
596	    {
597	        foreach (var entity in _dialogueState.OptionEntities)
598	        {
599	            if (entity.IsAlive) entity.Dispose();
600	        }
601	        _dialogueState.OptionEntities.Clear();
602	    }
603	
604	    private void HideIndicator()
605	    {
606	        if (_dialogueState.IndicatorEntity.Has<VisibleComponent>())
607	            _dialogueState.IndicatorEntity.Remove<VisibleComponent>();
608	
609	        // UI render target always renders regardless of VisibleComponent — clear the texture
610	        // so MasterRenderSystem skips drawing the stale DrawComponent.
611	        ref var indicatorDraw = ref _dialogueState.IndicatorEntity.Get<DrawComponent>();
612	        indicatorDraw.Texture = null;
613	    }
614	
615	    // --- Deactivation ---
616	
617	    private void DeactivateDialogue()
618	    {
619	        // Drop any pending command-continue so a command that coincides with the end of a
620	        // conversation (e.g. <<stop>>) can't leak a stray Continue() into the next dialogue.
621	        _pendingContinue = false;
622	        _dialogueState.IsActive = false;
623	        _dialogueState.WasTriggered = false;
624	        _dialogueState.CurrentPhase = DialoguePhase.None;
625	        _dialogueState.WaitingForInput = false;
626	        _dialogueState.CurrentSpeaker = null;
627	
628	        HideOptions();
629	
630	        // Hide box (and inner balloon)
631	        if (_dialogueState.BoxEntity.Has<VisibleComponent>())
632	            _dialogueState.BoxEntity.Remove<VisibleComponent>();
633	
634	        var boxDraw = _dialogueState.BoxEntity.Get<DrawComponent>();
635	        boxDraw.Texture = null;
636	
637	        if (_balloonMode)
638	        {
639	            if (_balloonEntity.Has<VisibleComponent>())
640	                _balloonEntity.Remove<VisibleComponent>();
641	            _balloonEntity.Get<DrawComponent>().Texture = null;
642	        }
643	
644	        // Clear text
645	        ref var dynamicText = ref _dialogueState.TextEntity.Get<DynamicTextComponent>();
646	        dynamicText.VisibleCharacterCount = 0;
647	        dynamicText.IsRevealed = false;
648	        dynamicText.TextContent = "";
649	
650	        var textDraw = _dialogueState.TextEntity.Get<DrawComponent>();
651	        textDraw.Text = null;
652	        textDraw.Font = null;
653	
654	        // Hide indicator
655	        HideIndicator();
656	        var indicatorDraw = _dialogueState.IndicatorEntity.Get<DrawComponent>();
657	        indicatorDraw.Texture = null;
658	
659	        _world.Publish(new DialogueActiveMessage(false));
660	    }
661	
662	    public void Dispose()
663	    {
664	        GC.SuppressFinalize(this);
665	    }
666	}
