380	    private Entity CreateWall(Rectangle bounds, HashSet<int> activeLayers)
381	    {
382	        var wall = _world.CreateEntity();
383	        wall.Set(new TransformComponent(Vector2.Zero));
384	        wall.Set(new BoxColliderComponent(bounds, activeLayers));
385	        return wall;
386	    }
