654	    public void Dispose()
655	    {
656	        UpdateSystem.Dispose();
657	        DrawSystem.Dispose();
658	        foreach (var rt in _renderTargets.Values) rt.Dispose();
659	        _world.Dispose();
660	        GC.SuppressFinalize(this);
661	    }
662	}
