307	    /// Builds a nine-patch (corner = <paramref name="corner"/> px) from a finished panel sprite
308	    /// at <paramref name="r"/> on a sheet: corners kept at source size, edges + centre sampled as
309	    /// 1px strips and stretched. Lets the wide box/balloon panels scale without warping corners.
310	    private static NinePatchInfo Panel9(Rectangle r, int corner)
311	    {
312	        int x = r.X, y = r.Y, w = r.Width, h = r.Height, c = corner;
313	        return new NinePatchInfo(
314	            c,
315	            new Rectangle(x, y, c, c),                 // top-left
316	            new Rectangle(x + c, y, 1, c),             // top (stretched horizontally)
317	            new Rectangle(x + w - c, y, c, c),         // top-right
318	            new Rectangle(x, y + c, c, 1),             // left (stretched vertically)
319	            new Rectangle(x + c, y + c, 1, 1),         // centre (stretched both ways)
320	            new Rectangle(x + w - c, y + c, c, 1),     // right
321	            new Rectangle(x, y + h - c, c, c),         // bottom-left
322	            new Rectangle(x + c, y + h - c, 1, c),     // bottom
323	            new Rectangle(x + w - c, y + h - c, c, c));// bottom-right
324	    }
